(window.BUNKAZAI_DETAIL=window.BUNKAZAI_DETAIL||{})["c53"]=[{"id":"00009015","register_sub_id":"101","register_pk":"162375","name":"平松家住宅外便所・炭小屋及び作業小屋","kana":"ひらまつけじゅうたくそとべんじょ・すみごやおよびさぎょうごや","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"長野県","address":"長野県上高井郡小布施町大字小布施1947","lat":36.70177172,"lng":138.30977201,"geo_status":"db","era":"明治40年","year":1907,"year_source":"db","year_min":1907,"year_max":1907,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積29㎡","structure_material":"木造平屋建","registered":"2011.10.28(平成23.10.28)","register_no":"20 － 0412","desc":"敷地東面北寄り、納屋の北側に並び建つ。桁行１３．３ｍ梁間１．８ｍ、木造平屋建、切妻造桟瓦葺で、南から外便所、炭小屋、作業小屋を設ける。中塗仕上げで腰壁を板張とし、西面に各出入口を開く。蚕室、納屋とともに一体的な屋敷景観を構成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009015"},{"id":"00009014","register_sub_id":"101","register_pk":"162374","name":"平松家住宅納屋","kana":"ひらまつけじゅうたくなや","category":"住宅","subcategory":"建築物","type_guess":"茶室・離れ","type_guess_confidence":"high","period":"明治","pref":"長野県","address":"長野県上高井郡小布施町大字小布施1947","lat":36.70166265,"lng":138.30974891,"geo_status":"db","era":"明治40年","year":1907,"year_source":"db","year_min":1907,"year_max":1907,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積32㎡","structure_material":"木造平屋建","registered":"2011.10.28(平成23.10.28)","register_no":"20 － 0411","desc":"敷地東面中央、外便所に接して建つ。桁行６．６ｍ梁間４．７ｍ、木造平屋建、切妻造桟瓦葺である。漆喰仕上げで腰を下見板張とし、中庭に面した西面に出入口を開く。内部は板張で、出入口には板戸を開く。蚕室とともに旧家の表構えを整える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009014"},{"id":"00009011","register_sub_id":"101","register_pk":"162371","name":"平松家住宅南土蔵","kana":"ひらまつけじゅうたくみなみどぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"江戸","pref":"長野県","address":"長野県上高井郡小布施町大字小布施1947","lat":36.70161517,"lng":138.30943069,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"土蔵造2階建、瓦葺、建築面積43㎡","structure_material":"土蔵造2階建","registered":"2011.10.28(平成23.10.28)","register_no":"20 － 0408","desc":"敷地南面の道路沿い、蚕室の西隣に建つ。桁行７．６ｍ梁間４．０ｍ、土蔵造二階建、切妻造、置屋根式の桟瓦葺である。中塗仕上げで北面に出入口を開き、庇を付ける。出入口に土戸と板戸、格子戸を装置するなど、簡素ながらも丁寧な造りになる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009011"},{"id":"00006680","register_sub_id":"101","register_pk":"107663","name":"藤田家住宅表門","kana":"ふじたけじゅうたくおもてもん","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"明治","pref":"長野県","address":"長野県長野市松代町松代1344-1","lat":36.55710237,"lng":138.20168375,"geo_status":"db","era":"明治期","year":1890,"year_source":"estimated","year_min":1868,"year_max":1912,"year_label":"明治期","structure":"木造、瓦葺、間口4.1m","structure_material":"木造","registered":"2007.12.05(平成19.12.05)","register_no":"20 － 0325","desc":"仲間部屋と土蔵の間に建つ。切妻造桟瓦葺の１間薬医門で、南北に袖塀を付設し、仲間部屋および土蔵と接続し、北側の袖塀には潜戸を開く。仲間部屋および土蔵と連続して重厚な表構えを造り、明治の再建であるが、武家屋敷の歴史を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006680"},{"id":"00006679","register_sub_id":"101","register_pk":"107662","name":"藤田家住宅土蔵","kana":"ふじたけじゅうたくどぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"長野県","address":"長野県長野市松代町松代1344-1","lat":36.55715276,"lng":138.20167745,"geo_status":"db","era":"明治期","year":1890,"year_source":"estimated","year_min":1868,"year_max":1912,"year_label":"明治期","structure":"土蔵造2階建、瓦葺、建築面積16㎡","structure_material":"土蔵造2階建","registered":"2007.12.05(平成19.12.05)","register_no":"20 － 0324","desc":"敷地の東面北寄り、通りに面して建つ。桁行２間梁間２間、土蔵造２階建、南北棟の切妻造桟瓦葺で、西面に蔵前をつける。外壁は中塗仕上げ。もとは軒裏も含めた全体が塗籠であったとみられる。窓枠まわりも丁寧に仕上げており、歴史的な景観を形成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006679"},{"id":"00007630","register_sub_id":"101","register_pk":"108612","name":"古田晁記念館展示室","kana":"ふるたあきらきねんかんてんじしつ","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"low","period":"昭和前","pref":"長野県","address":"長野県塩尻市大字北小野3035-3","lat":36.05045831,"lng":137.96588827,"geo_status":"db","era":"昭和前期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和前期","structure":"土蔵造2階建、瓦葺、建築面積79㎡","structure_material":"土蔵造2階建","registered":"2009.04.28(平成21.04.28)","register_no":"20 － 0347","desc":"敷地の西寄りに東面して建つ。桁行１１ｍ梁間５．５ｍ、２階建、寄棟造桟瓦葺で、東面に下屋を付ける。土蔵造を基本として、１階周囲を腰まで海鼠壁とする。２階は座敷３室を配し、廊下などの開口を広く設けてガラス窓を建て、開放的なつくりとする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007630"},{"id":"00007632","register_sub_id":"101","register_pk":"108614","name":"古田晁記念館門","kana":"ふるたあきらきねんかんもん","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"昭和前","pref":"長野県","address":"長野県塩尻市大字北小野3035-3","lat":36.050327,"lng":137.966187,"geo_status":"db","era":"昭和前期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和前期","structure":"木造、瓦葺、間口1.8m、左右袖塀付","structure_material":"木造","registered":"2009.04.28(平成21.04.28)","register_no":"20 － 0349","desc":"敷地の東寄りに建つ間口１．８ｍの腕木門。切妻造桟瓦葺で、両開板戸を吊る。左右に折曲りに延びる袖塀も、石積基礎上、腰板張で上部漆喰壁とし、桟瓦を葺き、格式あるつくりである。通りから矩折れに門を潜る配置で、伝統的な屋敷構えを留めている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007632"},{"id":"00007631","register_sub_id":"101","register_pk":"108613","name":"古田晁記念館渡廊下","kana":"ふるたあきらきねんかんわたりろうか","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"長野県","address":"長野県塩尻市大字北小野3035-3","lat":36.050407,"lng":137.96596427,"geo_status":"db","era":"昭和前期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和前期","structure":"木造2階建、銅板葺、建築面積12㎡","structure_material":"木造2階建","registered":"2009.04.28(平成21.04.28)","register_no":"20 － 0348","desc":"展示室２階の東面南端と本館との間を繋ぐ廊下で、木造２階建、切妻造銅板葺。やや傾斜して架け渡した丸太を土台とし、柱を建て、全柱間に廊下の傾斜に合わせて菱形としたガラス戸を入れる。化粧屋根裏天井にも丸太を使用し、軽快な数寄屋風意匠でまとめる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007631"},{"id":"00003541","register_sub_id":"101","register_pk":"104531","name":"ふれあい館しらふじ（旧丸田医院）雑蔵","kana":"ふれあいかんしらふじ（きゅうまるたいいん）ざつぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"長野県","address":"長野県須坂市大字須坂32-1","lat":36.653877,"lng":138.314438,"geo_status":"db","era":"明治8頃","year":1875,"year_source":"db","year_min":1875,"year_max":1875,"year_label":null,"structure":"土蔵造平屋建、瓦葺、建築面積20㎡","structure_material":"土蔵造平屋建","registered":"2003.09.19(平成15.09.19)","register_no":"20 － 0145","desc":"敷地北東隅に建つ平屋建土蔵で，資材等を収納していた。東西棟の切妻造，桟瓦葺で，西妻に戸口を設ける。外壁は漆喰塗だが，街路に面した北面は腰を横板張とし，塀との連続性が保たれている。屋敷の後方を整えるとともに，街路景観をかたちづくっている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003541"},{"id":"00003537","register_sub_id":"101","register_pk":"104527","name":"ふれあい館しらふじ（旧丸田医院）主屋","kana":"ふれあいかんしらふじ（きゅうまるたいいん）しゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"長野県","address":"長野県須坂市大字須坂32-1","lat":36.65377414,"lng":138.31432242,"geo_status":"db","era":"明治8","year":1875,"year_source":"db","year_min":1875,"year_max":1875,"year_label":null,"structure":"木造2階建、瓦葺、建築面積163㎡","structure_material":"木造2階建","registered":"2003.09.19(平成15.09.19)","register_no":"20 － 0141","desc":"木造２階建，東西棟の切妻造，桟瓦葺，平入で，南面を正面として敷地北寄りに建つ。街路に向かう西妻は漆喰大壁とし，ほかは真壁造になる。旧須坂藩勘定奉行の浦野氏が建てたもので，床や付書院などを構えた瀟洒な座敷廻りに，地方の武家住宅の伝統が伺える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003537"},{"id":"00003543","register_sub_id":"101","register_pk":"104533","name":"ふれあい館しらふじ（旧丸田医院）築地塀","kana":"ふれあいかんしらふじ（きゅうまるたいいん）ついじべい","category":"住宅","subcategory":"その他工作物","type_guess":"塀","type_guess_confidence":"high","period":"明治","pref":"長野県","address":"長野県須坂市大字須坂32-1","lat":36.65365784,"lng":138.31432504,"geo_status":"db","era":"明治8頃","year":1875,"year_source":"db","year_min":1875,"year_max":1875,"year_label":null,"structure":"土塀、瓦葺、延長20m","structure_material":"土塀","registered":"2003.09.19(平成15.09.19)","register_no":"20 － 0147","desc":"長屋門の左右に延び，北側は土蔵に接続し，南側はコの字型に長屋門南西隅を囲む。桟瓦葺の小屋根を架けた土塀で，敷地側に控柱を建てて屋根を葺き下ろし，道具等を収納する。玉石積の上を切石で見切り，腰は丁寧な磨き漆喰とし，屋敷正面の景観を整えている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003543"},{"id":"00003540","register_sub_id":"101","register_pk":"104530","name":"ふれあい館しらふじ（旧丸田医院）土蔵","kana":"ふれあいかんしらふじ（きゅうまるたいいん）どぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"長野県","address":"長野県須坂市大字須坂32-1","lat":36.6537851,"lng":138.3141899,"geo_status":"db","era":"明治8頃","year":1875,"year_source":"db","year_min":1875,"year_max":1875,"year_label":null,"structure":"土蔵造3階建、瓦葺、建築面積20㎡","structure_material":"土蔵造3階建","registered":"2003.09.19(平成15.09.19)","register_no":"20 － 0144","desc":"屋敷の北西隅にある３階建土蔵。東西棟の切妻造，桟瓦葺で，南面に庇付の扉口と３階窓，東面に２階窓を設ける。石積基礎に建ち，漆喰塗の外壁は２段の水切をつける。深い軒や高い棟積などが，立ちの高い外観と相俟って，街路景観のアクセントとなっている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003540"},{"id":"00003542","register_sub_id":"101","register_pk":"104532","name":"ふれあい館しらふじ（旧丸田医院）長屋門","kana":"ふれあいかんしらふじ（きゅうまるたいいん）ながやもん","category":"住宅","subcategory":"建築物","type_guess":"門","type_guess_confidence":"high","period":"明治","pref":"長野県","address":"長野県須坂市大字須坂32-1","lat":36.65368538,"lng":138.31423755,"geo_status":"db","era":"明治8頃","year":1875,"year_source":"db","year_min":1875,"year_max":1875,"year_label":null,"structure":"木造2階建、瓦葺、建築面積26㎡","structure_material":"木造2階建","registered":"2003.09.19(平成15.09.19)","register_no":"20 － 0146","desc":"屋敷正面の西辺，街路沿いに建つ。木造２階建，南北棟の切妻造，桟瓦葺で，桁行約７ｍと小さいが，１階南を門口とし，１階北及び２階を物置とする。外壁は漆喰塗で，軒裏は垂木を波型に塗り籠めて，整然とした屋敷の正面構えをつくりだしている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003542"},{"id":"00005186","register_sub_id":"101","register_pk":"106176","name":"法蔵寺裏門","kana":"ほうぞうじうらもん","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"昭和前","pref":"長野県","address":"長野県安曇野市豊科5716","lat":36.30219325,"lng":137.90569841,"geo_status":"db","era":"昭和3／平成10移築","year":1928,"year_source":"db","year_min":1928,"year_max":1928,"year_label":null,"structure":"木造、瓦葺、間口2.4m","structure_material":"木造","registered":"2005.12.26(平成17.12.26)","register_no":"20 － 0254","desc":"境内の南西隅にある通用門。１間１戸の腕木門で，屋根は起りのある切妻造，桟瓦葺で，左右に小屋根付の袖塀をつける。軒は木舞打で，流水をあしらった欄間など数寄屋風の趣向を凝らし，絵様付の破風板や雲文の懸魚など，規模は小さいが細部にも冴えを見せる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005186"},{"id":"00012147","register_sub_id":"101","register_pk":"352946","name":"本折井家住宅主屋","kana":"ほんおりいけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"長野県","address":"長野県松本市白板一丁目81","lat":36.236131,"lng":137.96012,"geo_status":"db","era":"寛政2年(1790)／昭和中期改修","year":1790,"year_source":"db","year_min":1790,"year_max":1790,"year_label":null,"structure":"木造平屋一部2階建、金属板葺、建築面積422㎡","structure_material":"木造平屋一部2階建","registered":"2018.03.27(平成30.03.27)","register_no":"20-518","desc":"間口一〇間、奥行一〇間の本棟造で、式台玄関と大戸口を並べ床上部は二列六室。前方へカミザシキを突出させ、イリカワを廻らし上便所を備えた格式高い接客空間を持つ。八寸角の大黒柱や重厚な梁組に対し、座敷構えは瀟洒な意匠であり、当地域を代表する民家。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012147"},{"id":"00014383","register_sub_id":"101","register_pk":"511372","name":"正木屋山浦家住宅南蔵","kana":"まさきややまうらけじゅうたくみなみぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"江戸","pref":"長野県","address":"長野県上伊那郡宮田村3256","lat":35.76695,"lng":137.94120556,"geo_status":"db","era":"慶応4年(1868)／昭和30年代改修","year":1868,"year_source":"db","year_min":1868,"year_max":1868,"year_label":null,"structure":"木造2階建、瓦葺、建築面積94㎡","structure_material":"木造2階建","registered":"2022.10.31(令和4.10.31)","register_no":"20 - 0628","desc":"伊那街道の宮田宿に位置する酒造業の土蔵。二階建切妻造の東西棟を二棟並べ、東を米蔵、西を座敷蔵とし、桟瓦葺屋根を一体で架ける。外壁は漆喰仕上で腰は海鼠壁。座敷蔵一階は二箇所に床を設け、周囲の建具を板絵で飾る。宿場の華やかな文化を伝える土蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014383"},{"id":"00005148","register_sub_id":"101","register_pk":"106138","name":"松下家住宅主屋","kana":"まつしたけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"長野県","address":"長野県長野市松代町松代946","lat":36.56381452,"lng":138.20288814,"geo_status":"db","era":"明治末期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治末期","structure":"木造2階建、瓦葺、建築面積237㎡","structure_material":"木造2階建","registered":"2005.12.26(平成17.12.26)","register_no":"20 － 0216","desc":"西面する道路に接して建つ。桁行１０間，梁間５間半の規模，切妻造，桟瓦葺，土蔵造２階建で，正面及び背面にそれぞれ下屋を張出す。外観は白漆喰仕上げとし，１階の連続する格子，２階の４連の窓が外観を特徴づけ，鍛冶町の歴史的景観を作り上げる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005148"},{"id":"00005138","register_sub_id":"101","register_pk":"106128","name":"美濃屋土蔵","kana":"みのやどぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"長野県","address":"長野県長野市松代町松代501","lat":36.561955,"lng":138.19872221,"geo_status":"db","era":"明治中期","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"土蔵造2階建、瓦葺、建築面積30㎡","structure_material":"土蔵造2階建","registered":"2005.12.26(平成17.12.26)","register_no":"20 － 0206","desc":"敷地奥，北寄りに東面して建つ。切妻造，桟瓦葺の２階建土蔵。東西の妻壁２階部分に窓を開く。当初は白漆喰仕上であった外壁を，現在は鉄板で覆う。松代商家に典型的な土蔵の造りを見せ，商家の敷地後方の景観を形成している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005138"},{"id":"00000769","register_sub_id":"101","register_pk":"132568","name":"宮澤家住宅腕木門","kana":"みやざわけじゅうたくうでぎもん","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"昭和前","pref":"長野県","address":"長野県安曇野市三郷明盛3042","lat":36.274201,"lng":137.89941647,"geo_status":"db","era":"昭和11頃","year":1936,"year_source":"db","year_min":1936,"year_max":1936,"year_label":null,"structure":"木造腕木門，左右袖塀延長5m附属","structure_material":"木造腕木門","registered":"1998.09.02(平成10.09.02)","register_no":"20 － 0011","desc":"玄関右脇にあり，座敷前の庭園を区切る塀重門で，扉は一枚板で乳金具付き棟に鯱を置く重厚な構えになる。左右に屋根付きの袖塀が付くが，門際の１間分が斜め前方に開く形になり，腰下は下見板貼とする。小規模な門ながら，主屋の表廻りを整えている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000769"},{"id":"00000770","register_sub_id":"101","register_pk":"101760","name":"宮澤家住宅冠木門","kana":"みやざわけじゅうたくかぶきもん","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"大正","pref":"長野県","address":"長野県安曇野市三郷明盛3042","lat":36.27452631,"lng":137.8990923,"geo_status":"db","era":"大正9頃","year":1920,"year_source":"db","year_min":1920,"year_max":1920,"year_label":null,"structure":"木造冠木門","structure_material":"木造冠木門","registered":"1998.09.02(平成10.09.02)","register_no":"20 － 0012","desc":"屋敷地の北側にある裏門で，冠木の上に小屋根を付けた特異な形態になる。内開きの門扉が設けられ，左右に袖塀が付く。かつては馬が出入りしたといわれ，簡素ながら堂々とした構えになり，屋敷地背後の景観を引き立てている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000770"},{"id":"00000764","register_sub_id":"101","register_pk":"101754","name":"宮澤家住宅主屋","kana":"みやざわけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和前","pref":"長野県","address":"長野県安曇野市三郷明盛3042","lat":36.27424067,"lng":137.89921925,"geo_status":"db","era":"昭和11","year":1936,"year_source":"db","year_min":1936,"year_max":1936,"year_label":null,"structure":"木造２階建，瓦葺，建築面積270㎡","structure_material":"木造２階建","registered":"1998.09.02(平成10.09.02)","register_no":"20 － 0006","desc":"宮澤家はこの地方の旧家で，先々代は村長，先代は製糸業を経営した。主屋は，入母屋造，２階建で軒の深い重厚な外観になる。戦前期の和風住宅の一典型で，座敷廻りの欄間彫刻は見応えがある。２階の３２畳の大広間は，公私にわたる接客場として使用された。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000764"},{"id":"00005136","register_sub_id":"101","register_pk":"106126","name":"宮澤家住宅主屋","kana":"みやざわけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"大正","pref":"長野県","address":"長野県長野市松代町松代417","lat":36.56203976,"lng":138.19997552,"geo_status":"db","era":"大正末期","year":1922,"year_source":"estimated","year_min":1919,"year_max":1926,"year_label":"大正末期","structure":"木造2階建、瓦葺、建築面積61㎡","structure_material":"木造2階建","registered":"2005.12.26(平成17.12.26)","register_no":"20 － 0204","desc":"国道に南面して建つ。桁行７間，梁間３間規模，寄棟造，桟瓦葺の木造２階建で，正面に下屋を出す。２階外壁は白漆喰で塗込める。松代町の住宅に白漆喰を用い始めた初期の事例で，２階戸袋の額縁や２階軒下の塗込めの意匠に特徴を見せる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005136"},{"id":"00000766","register_sub_id":"101","register_pk":"101756","name":"宮澤家住宅土蔵","kana":"みやざわけじゅうたくどぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"長野県","address":"長野県安曇野市三郷明盛3042","lat":36.27430868,"lng":137.89904016,"geo_status":"db","era":"明治18","year":1885,"year_source":"db","year_min":1885,"year_max":1885,"year_label":null,"structure":"土蔵造２階建，瓦葺，建築面積70㎡","structure_material":"土蔵造２階建","registered":"1998.09.02(平成10.09.02)","register_no":"20 － 0008","desc":"切妻造，２階建，平入の中規模の土蔵で，正面（主屋側）に幅一間の塗込めの庇が付く。開口部の少ない土蔵で，軒廻りは塗込の垂木や母屋を見せる点に特徴がある。腰下はなまこ壁仕上げとするが，正面は亀甲模様とし，その他は四半貼りと変化をつけている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000766"},{"id":"00000771","register_sub_id":"101","register_pk":"101761","name":"宮澤家住宅納屋・旧鶏小屋","kana":"みやざわけじゅうたくなや・きゅうにわとりごや","category":"住宅","subcategory":"建築物","type_guess":"茶室・離れ","type_guess_confidence":"high","period":"大正","pref":"長野県","address":"長野県安曇野市三郷明盛3042","lat":36.27450704,"lng":137.89917278,"geo_status":"db","era":"大正9頃","year":1920,"year_source":"db","year_min":1920,"year_max":1920,"year_label":null,"structure":"木造平屋建，瓦葺，建築面積50㎡","structure_material":"木造平屋建","registered":"1998.09.02(平成10.09.02)","register_no":"20 － 0013","desc":"屋敷地の北東部を囲う位置に建てられた付属屋で，冠木門脇の旧鶏小屋及びこれに接続する南側の納屋からなる。納屋は，敷地境の水路に沿って建つが，外観は旧鶏小屋と同じ真壁造で腰下を縦板貼りとし貫を見せる構造になり，外観は屋根塀のように見せている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000771"},{"id":"00000765","register_sub_id":"101","register_pk":"101755","name":"宮澤家住宅はなれ","kana":"みやざわけじゅうたくはなれ","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"low","period":"昭和前","pref":"長野県","address":"長野県安曇野市三郷明盛3042","lat":36.27417947,"lng":137.89907417,"geo_status":"db","era":"昭和10頃","year":1935,"year_source":"db","year_min":1935,"year_max":1935,"year_label":null,"structure":"木造一部土蔵造平屋建，瓦葺，建築面積75㎡","structure_material":"木造一部土蔵造平屋建","registered":"1998.09.02(平成10.09.02)","register_no":"20 － 0007","desc":"主屋に先立って宅地の西側に建築され，完成後は離れとして利用されている切妻造，桟瓦葺の平屋建物。外観は，主屋側は木部をみせる造作とするが，背面側は大壁造，漆喰塗の土蔵風に造り腰下はなまこ壁として北側の土蔵と意匠を揃えている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000765"},{"id":"00000768","register_sub_id":"101","register_pk":"132567","name":"宮澤家住宅門柱・石塀・屋根塀","kana":"みやざわけじゅうたくもんちゅう・いしべい・やねべい","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"大正","pref":"長野県","address":"長野県安曇野市三郷明盛3042","lat":36.27425994,"lng":137.8993326,"geo_status":"db","era":"大正9頃・昭和11頃","year":1920,"year_source":"db","year_min":1920,"year_max":1920,"year_label":null,"structure":"石造塀，木造屋根塀からなる，総延長90m，石造門柱附属","structure_material":"石造塀","registered":"1998.09.02(平成10.09.02)","register_no":"20 － 0010","desc":"屋敷地の東面から南面を囲う塀及び門柱で，石造の門及び塀は主屋再建時に改築されたもの。表門は親柱のみで大柄の御影石切石を３段重ね頭部に球状の飾りを置く洒落た造形になる。石塀は，敷地南面で標準的な屋根塀と接続し，ともに屋敷構えを整えている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000768"},{"id":"00014820","register_sub_id":"101","register_pk":"519078","name":"桃澤家住宅主屋","kana":"ももざわけじゅうたくおもや","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"長野県","address":"長野県上伊那郡飯島町本郷279","lat":35.65771667,"lng":137.9403,"geo_status":"db","era":"江戸後期／明治後期増築、昭和30年頃・令和元年改修","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造平屋建、鉄板葺、建築面積236㎡","structure_material":"木造平屋建","registered":"2024.03.06(令和6.03.06)","register_no":"20 - 0642","desc":"天竜川沿いの農村集落に位置する旧家の主屋。切妻造平入鉄板葺で、東面の中央に玄関、南寄りに式台を構える。間取りは部屋を三列に並べて、南列には３間続きの座敷を配し、西端は床と付書院を備えた上座敷とする。大規模な切妻造屋根が旧家の格式を示す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014820"},{"id":"00002394","register_sub_id":"101","register_pk":"103384","name":"矢口家住宅主屋","kana":"やぐちけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"長野県","address":"長野県北安曇郡小谷村大字千国乙3160","lat":36.75686885,"lng":137.8956677,"geo_status":"db","era":"明治8","year":1875,"year_source":"db","year_min":1875,"year_max":1875,"year_label":null,"structure":"木造2階建、茅葺、建築面積169㎡","structure_material":"木造2階建","registered":"2001.10.12(平成13.10.12)","register_no":"20 － 0099","desc":"千国街道（塩の道）千国宿の中心地に在り，街道沿いに西面して建つ。代々大工を業とする家の住居で，寄棟造，茅葺，桁行７間半，梁間５間半とする。正面及び南面の２階を真壁造，他を下見板張としたハーフティンバー風の趣をもつ民家建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002394"},{"id":"00011302","register_sub_id":"101","register_pk":"209139","name":"柳田國男館（旧喜談書屋）","kana":"やなぎたくにおかん（きゅうきたんしょおく）","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"長野県","address":"長野県飯田市追手町二丁目","lat":35.51168,"lng":137.832037,"geo_status":"db","era":"昭和2／昭和63移築","year":1927,"year_source":"db","year_min":1927,"year_max":1927,"year_label":null,"structure":"木造2階建、瓦葺、建築面積155㎡","structure_material":"木造2階建","registered":"2016.11.29(平成28.11.29)","register_no":"20－0502","desc":"もと世田谷区成城の柳田國男宅の書斎。国際連盟からの帰朝時に建てられ、民俗学創出の拠点となった。ポーチを備えた二階建で、ハーフティンバー調の意匠を見せ、二重サッシュを用いるなどの特徴がある。一階書斎部は大空間に書棚を並べ、独特の空間となる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011302"},{"id":"00005150","register_sub_id":"101","register_pk":"106140","name":"山岸家住宅長屋門","kana":"やまぎしけじゅうたくながやもん","category":"住宅","subcategory":"建築物","type_guess":"門","type_guess_confidence":"high","period":"大正","pref":"長野県","address":"長野県長野市松代町松代1220","lat":36.55962873,"lng":138.20369548,"geo_status":"db","era":"大正後期","year":1922,"year_source":"estimated","year_min":1919,"year_max":1926,"year_label":"大正後期","structure":"木造2階建、瓦葺、建築面積121㎡","structure_material":"木造2階建","registered":"2005.12.26(平成17.12.26)","register_no":"20 － 0218","desc":"敷地北辺にあり，養蚕場などにも用いられた。東西棟の切妻造２階建，桟瓦葺で，両妻面に下屋を設け，１階はすべて床張であるが，正面中央に門口の構えを残す。外壁は土壁で，窓廻りに丁寧な縁取りを施す。たちの高いつくりで，街路景観をかたちづくっている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005150"},{"id":"00011134","register_sub_id":"101","register_pk":"205241","name":"山崎家及び臼井家別荘（セキスイハウスＡ型）","kana":"やまざきけおよびうすいけべっそう（せきすいはうすＡがた）","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和中","pref":"長野県","address":"長野県北佐久郡軽井沢町大字長倉字筒井711-37","lat":36.334002,"lng":138.606457,"geo_status":"db","era":"昭和38","year":1963,"year_source":"db","year_min":1963,"year_max":1963,"year_label":null,"structure":"鉄骨造平屋建、金属板葺、建築面積34㎡","structure_material":"鉄骨造平屋建","registered":"2016.08.01(平成28.08.01)","register_no":"20 - 0501","desc":"セキスイハウスＡ型は、軽量鉄骨にアルミサンドイッチパネルを取り付ける構法で作られ、居室に水まわりを備えた本格的な工業化住宅の国産第一号である。本住宅は、セキスイハウスＡ型国内唯一のほぼ完存する遺構として、我が国の戦後住宅史上価値が高い。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011134"},{"id":"00002392","register_sub_id":"101","register_pk":"103382","name":"山田旅館新土蔵","kana":"やまだりょかんしんどぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"長野県","address":"長野県北安曇郡小谷村大字中土18836","lat":36.86190966,"lng":137.981246,"geo_status":"db","era":"明治42","year":1909,"year_source":"db","year_min":1909,"year_max":1909,"year_label":null,"structure":"土蔵造2階建、鉄板葺、建築面積85㎡","structure_material":"土蔵造2階建","registered":"2001.10.12(平成13.10.12)","register_no":"20 － 0097","desc":"本館の東南方，道路から旅館にアプローチする入口際の石垣上に建つ。棟木墨書から建設年代と「大工棟梁 南小谷村 小倉朝治郎」らが判明している。現在は蔵前部が改造されて２階建となり「小谷温泉山田資料館」として公開されている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002392"},{"id":"00002391","register_sub_id":"101","register_pk":"103381","name":"山田旅館前土蔵","kana":"やまだりょかんまえどぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"長野県","address":"長野県北安曇郡小谷村大字中土18836","lat":36.86200159,"lng":137.98078107,"geo_status":"db","era":"明治18","year":1885,"year_source":"db","year_min":1885,"year_max":1885,"year_label":null,"structure":"土蔵造平屋建、鉄板葺、建築面積54㎡","structure_material":"土蔵造平屋建","registered":"2001.10.12(平成13.10.12)","register_no":"20 － 0096","desc":"本館から新館に至る小路を挟んで本館の西側に東面して建つ。南北棟，切妻造，置屋根形式の土蔵で，東面に土庇を設けて２戸前とする。棟木墨書から建築年代が判明しており，外部は腰を押縁下見，上部を白漆喰塗とし，土庇の柱上部や桁をも漆喰で塗廻す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002391"},{"id":"00015450","register_sub_id":"101","register_pk":"533465","name":"米山家住宅主屋","kana":"よねやまけじゅうたくおもや","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"長野県","address":"長野県上伊那郡中川村片桐4134","lat":35.63030556,"lng":137.92879444,"geo_status":"db","era":"江戸末期／昭和30年代・令和5年改修","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造平屋一部2階建、瓦葺、建築面積215㎡","structure_material":"木造平屋一部2階建","registered":"2025.08.06(令和7.08.06)","register_no":"20 - 0673","desc":"天竜川上流域の集落に立地する農家の主屋。桁行一三メートル、梁間一六メートル、切妻造妻入桟瓦葺で内部東半は広い土間、西半は二列六室を配す。小屋裏は養蚕など作業部屋とする。正面下屋桁を太い梁鼻で支えるなど豪壮なつくりで当地域特有の本棟造の好例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015450"},{"id":"00002541","register_sub_id":"101","register_pk":"103531","name":"利久堂酒井家住宅主屋","kana":"りきゅうどうさかいけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"長野県","address":"長野県長野市川合新田140","lat":36.62550526,"lng":138.20797845,"geo_status":"db","era":"明治20頃","year":1887,"year_source":"db","year_min":1887,"year_max":1887,"year_label":null,"structure":"木造平屋一部2階建、瓦葺、建築面積283㎡","structure_material":"木造平屋一部2階建","registered":"2001.11.20(平成13.11.20)","register_no":"20 － 0100","desc":"旧家であり，明治以来医院を開業した北村家の主屋として建設。越屋根を頂く養蚕農家の外観で，正面中央に式台玄関を構え，背面には隠居部屋等を突出す。上手端中央に主座敷を置いて表裏に入側を設け，土間部下手側に診療室と待合を設けるなど変形間取を持つ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002541"},{"id":"00002543","register_sub_id":"101","register_pk":"103533","name":"利久堂酒井家住宅土蔵","kana":"りきゅうどうさかいけじゅうたくどぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"長野県","address":"長野県長野市川合新田140","lat":36.62568798,"lng":138.20778927,"geo_status":"db","era":"明治20頃","year":1887,"year_source":"db","year_min":1887,"year_max":1887,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積79㎡","structure_material":"土蔵造2階建","registered":"2001.11.20(平成13.11.20)","register_no":"20 － 0102","desc":"主屋の西北方に建つ。南北棟，切妻造，桟瓦葺，平入の２階建土蔵で，桁行５間半，梁間２間半の規模を有する。北妻面に架けた下屋を東前方に延ばして北口門を設けるほか，東面には鉄造仕様の庇を架けて蔵前をとる。内部は２階とし，道具蔵として使用された。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002543"},{"id":"00002542","register_sub_id":"101","register_pk":"103532","name":"利久堂酒井家住宅長屋門","kana":"りきゅうどうさかいけじゅうたくながやもん","category":"住宅","subcategory":"建築物","type_guess":"門","type_guess_confidence":"high","period":"明治","pref":"長野県","address":"長野県長野市川合新田140","lat":36.625309,"lng":138.207764,"geo_status":"db","era":"明治20頃","year":1887,"year_source":"db","year_min":1887,"year_max":1887,"year_label":null,"structure":"木造平屋一部2階建、瓦葺、建築面積169㎡","structure_material":"木造平屋一部2階建","registered":"2001.11.20(平成13.11.20)","register_no":"20 － 0101","desc":"もと北村家は長野市街の南東方，犀川左岸近くに位置し，主屋の南方に間口約２５ｍ規模の東西棟，切妻造，桟瓦葺の長屋門を置く。西側部分の屋根は一段高く，東側部分が低く段違になっており，門構えは西側部分の東端にあって大きく重厚な門扉を内に開く。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002542"},{"id":"00002545","register_sub_id":"101","register_pk":"103535","name":"利久堂酒井家住宅庭塀","kana":"りきゅうどうさかいけじゅうたくにわべい","category":"住宅","subcategory":"その他工作物","type_guess":"塀","type_guess_confidence":"high","period":"明治","pref":"長野県","address":"長野県長野市川合新田140","lat":36.6253551,"lng":138.2079535,"geo_status":"db","era":"明治20頃","year":1887,"year_source":"db","year_min":1887,"year_max":1887,"year_label":null,"structure":"土塀、瓦葺、延長18m","structure_material":"土塀","registered":"2001.11.20(平成13.11.20)","register_no":"20 － 0104","desc":"主屋玄関上手脇から南の長屋門方に延びる屋根付塀で，長屋門手前で東に折れ曲がり，座敷庭を区画する。中間に一段棟を高くした中門を開く。塀の玄関側の面は土塀風の仕上げとし，座敷庭側の面は真壁造風として３間毎に石柱と鉄棒による控えをとる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002545"},{"id":"00002544","register_sub_id":"101","register_pk":"103534","name":"利久堂酒井家住宅味噌蔵","kana":"りきゅうどうさかいけじゅうたくみそぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"長野県","address":"長野県長野市川合新田140","lat":36.62558017,"lng":138.20776698,"geo_status":"db","era":"明治20頃","year":1887,"year_source":"db","year_min":1887,"year_max":1887,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積14㎡","structure_material":"土蔵造2階建","registered":"2001.11.20(平成13.11.20)","register_no":"20 － 0103","desc":"主屋の北西方，土蔵の南に接して建つ。南北棟，切妻造，桟瓦葺，平入の土蔵で，内部は２階とし，１階は床をはらずに土間とし味噌蔵として使用する。桁行２間，梁間２間半と小規模であるが，開口部の枠取りなどは丁寧な造りで重厚な趣きを感じさせる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002544"},{"id":"00003428","register_sub_id":"101","register_pk":"104418","name":"ロッジ欅旅館主屋","kana":"ろっじけやきりょかんしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"大正","pref":"長野県","address":"長野県北安曇郡小谷村大字千国乙1576","lat":36.74310452,"lng":137.88162221,"geo_status":"db","era":"大正12","year":1923,"year_source":"db","year_min":1923,"year_max":1923,"year_label":null,"structure":"木造2階建、茅葺、建築面積173㎡","structure_material":"木造2階建","registered":"2003.07.01(平成15.07.01)","register_no":"20 － 0135","desc":"桁行９間，梁間５間半，平入の民家で，小谷村で標準的な規模を持つ。茅葺，寄棟造で，大正１２年の建設と伝え，昭和４０年代からは民宿等として活用されている。内部は養蚕のために２階床が張られており，大正期の小谷村の暮らしを今日に伝える建造物である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003428"},{"id":"00013731","register_sub_id":"101","register_pk":"505269","name":"脇田和アトリエ山荘","kana":"わきたかずあとりえさんそう","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和後","pref":"長野県","address":"長野県北佐久郡軽井沢町大字軽井沢字野沢原1243-14他","lat":36.35089722,"lng":138.63331111,"geo_status":"db","era":"昭和45年","year":1970,"year_source":"db","year_min":1970,"year_max":1970,"year_label":null,"structure":"鉄筋コンクリート造一部木造2階建、鉄板葺、建築面積171㎡","structure_material":"鉄筋コンクリート造一部木造2階建","registered":"2021.02.26(令和3.02.26)","register_no":"20 － 0570","desc":"洋画家のアトリエ兼山荘。くの字形の長大な平面を東西に分け、一階をピロティとし主要な室は二階に配する。東棟はリビングや寝室等とし南に大きな開口を開けて庭を望む。西棟は矩形平面のアトリエと書斎。設計者吉村順三の作風が表れるモダニズム住宅の佳品。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013731"},{"id":"00003089","register_sub_id":"101","register_pk":"104079","name":"和田家住宅主屋","kana":"わだけじゅうたく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"長野県","address":"長野県諏訪郡富士見町落合12160","lat":35.91933033,"lng":138.25340147,"geo_status":"db","era":"明治39","year":1906,"year_source":"db","year_min":1906,"year_max":1906,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積155㎡","structure_material":"木造平屋建","registered":"2003.01.31(平成15.01.31)","register_no":"20 － 0109","desc":"桁行９間２尺梁行４間２尺規模，切妻造，もと板葺の養蚕農家で，内部は四間取りとし，東方土間の下手に馬屋を設けていた。諏訪地方高原部にみられる出梁造りによる深い軒に特徴がある。１０年程空家であったが，近年屋根葺替と内部改装を行い住宅として再生。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003089"},{"id":"00003090","register_sub_id":"101","register_pk":"104080","name":"和田家住宅土蔵","kana":"わだけじゅうたくどぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"長野県","address":"長野県諏訪郡富士見町落合12160","lat":35.91928372,"lng":138.25355654,"geo_status":"db","era":"明治30代","year":1897,"year_source":"db","year_min":1897,"year_max":1897,"year_label":null,"structure":"土蔵造2階建、鉄板葺、建築面積40㎡","structure_material":"土蔵造2階建","registered":"2003.01.31(平成15.01.31)","register_no":"20 － 0110","desc":"主屋の東に隣接して建つ。桁行３間梁間２間規模，東西棟の平入２階建土蔵で，前面に深い土庇をつくって作業場とし，北側背面には味噌倉を付属させる。近年の改装にあたり，主屋と一体的な屋根を架け，当地方にみられる「建てぐるみ」式風に整備された。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003090"},{"id":"00012366","register_sub_id":"101","register_pk":"531690","name":"伊佐治家住宅上座敷","kana":"いさじけじゅうたくかみざしき","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"江戸","pref":"岐阜県","address":"岐阜県可児郡御嵩町古屋敷字大王寺381","lat":35.42705556,"lng":137.11352222,"geo_status":"db","era":"嘉永3年(1850)／明治20年・同45年移築","year":1850,"year_source":"db","year_min":1850,"year_max":1850,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積92㎡","structure_material":"木造平屋建","registered":"2018.05.10(平成30.05.10)","register_no":"21-257","desc":"主屋南東隅に接続し、南北棟で建つ。入母屋造桟瓦葺の平屋建で、床付きの十畳二室を南北に並べ、南室では西面に切妻屋根の式台を構え、庭に面する南面に廊下と濡縁を設ける。北室は床脇を琵琶床とする。格式を備えつつ、数寄屋意匠を加味した瀟洒な客座敷。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012366"},{"id":"00012365","register_sub_id":"101","register_pk":"531689","name":"伊佐治家住宅主屋","kana":"いさじけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"岐阜県","address":"岐阜県可児郡御嵩町古屋敷字大王寺381","lat":35.42714167,"lng":137.11339167,"geo_status":"db","era":"江戸後期／江戸末期改修","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造平屋建、瓦葺、建築面積210㎡、中門付","structure_material":"木造平屋建","registered":"2018.05.10(平成30.05.10)","register_no":"21-256","desc":"西面する敷地奥に南面して建ち、切妻造桟瓦葺で下屋を廻らす。西半を広い土間とし、二列構成の居室部は上手に座敷二室と前後に畳縁、下手に四室を並べる。軸部は当地方の民家の特徴の一つ、四つ建形式を基本とし、土間に重厚な軸組を現す上質な近世民家。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012365"},{"id":"00012368","register_sub_id":"101","register_pk":"531692","name":"伊佐治家住宅茶室","kana":"いさじけじゅうたくちゃしつ","category":"住宅","subcategory":"建築物","type_guess":"茶室・離れ","type_guess_confidence":"high","period":"江戸","pref":"岐阜県","address":"岐阜県可児郡御嵩町古屋敷字大王寺381","lat":35.42737778,"lng":137.11325556,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造平屋建、瓦葺、建築面積14㎡","structure_material":"木造平屋建","registered":"2018.05.10(平成30.05.10)","register_no":"21-259","desc":"敷地北西隅に東西棟で建つ。桁行3･7メートル梁間3･7メートル、切妻造桟瓦葺である。壁は真壁で垂木に細丸太を使う。内部は六畳一室で東面に床と押入をつくり、床柱は杉絞り丸太、床框は黒漆塗、壁は浅葱色とする。屋敷構えに風情を醸す端正な茶室である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012368"},{"id":"00012367","register_sub_id":"101","register_pk":"531691","name":"伊佐治家住宅土蔵","kana":"いさじけじゅうたくどぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"岐阜県","address":"岐阜県可児郡御嵩町古屋敷字大王寺381","lat":35.4273,"lng":137.11341111,"geo_status":"db","era":"明治初期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治初期","structure":"土蔵造2階建、瓦葺、建築面積21㎡","structure_material":"土蔵造2階建","registered":"2018.05.10(平成30.05.10)","register_no":"21-258","desc":"主屋土間部の後方に東西棟で建つ。土蔵造二階建、桁行4･7メートル梁間3･7メートル、切妻造桟瓦葺である。外壁は中塗仕上で開口部周囲や軒裏を漆喰塗とする。南面を戸口として扉枠をつくり、下屋を設ける。下階はもと米蔵、上階は什器などを納めた。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012367"},{"id":"00012369","register_sub_id":"101","register_pk":"531693","name":"伊佐治家住宅長屋門","kana":"いさじけじゅうたくながやもん","category":"住宅","subcategory":"建築物","type_guess":"門","type_guess_confidence":"high","period":"江戸","pref":"岐阜県","address":"岐阜県可児郡御嵩町古屋敷字大王寺381","lat":35.42714722,"lng":137.11321944,"geo_status":"db","era":"江戸後期","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造平屋建、瓦葺、建築面積73㎡","structure_material":"木造平屋建","registered":"2018.05.10(平成30.05.10)","register_no":"21-260","desc":"敷地西側の旧街道から後退し、野面石積の石垣上に建つ。桁行20メートルに及ぶ南北棟の切妻造桟瓦葺で南寄りに門口を開く。外壁は中塗仕上の腰簓子下見板張、開口部に出格子を設けるなど重厚なつくりとする。格式ある表構えをつくる、風格を備えた長屋門。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012369"},{"id":"00013546","register_sub_id":"101","register_pk":"504913","name":"市原家住宅主屋","kana":"いちはらけじゅうたくおもや","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"岐阜県","address":"岐阜県岐阜市大字古市場字西畑196-5他","lat":35.46413611,"lng":136.72105556,"geo_status":"db","era":"明治16年／大正5年増築","year":1883,"year_source":"db","year_min":1883,"year_max":1883,"year_label":null,"structure":"木造2階建、瓦葺、建築面積285㎡","structure_material":"木造2階建","registered":"2021.02.04(令和3.02.04)","register_no":"21 － 0284","desc":"黒野城跡の北西部に位置する。二階建切妻造桟瓦葺。玄関から中廊下を通して上手に応接室など三室、下手に台所、居間、座敷等を配する。座敷からさらに数寄屋風書院を別棟で接続し、松尾流九代松尾宗見の指導で茶室を増築した。格調高い地元名士の邸宅。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013546"},{"id":"00013547","register_sub_id":"101","register_pk":"504914","name":"市原家住宅長屋門","kana":"いちはらけじゅうたくながやもん","category":"住宅","subcategory":"建築物","type_guess":"門","type_guess_confidence":"high","period":"明治","pref":"岐阜県","address":"岐阜県岐阜市大字古市場字西畑196-5他","lat":35.46411944,"lng":136.72138333,"geo_status":"db","era":"明治6年／平成30年改修","year":1873,"year_source":"db","year_min":1873,"year_max":1873,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積71㎡","structure_material":"木造平屋建","registered":"2021.02.04(令和3.02.04)","register_no":"21 － 0285","desc":"敷地東辺に位置する長屋門。切妻造桟瓦葺で中央に門口をあけ、腰を割竹張、上部を漆喰塗とする。内部は左右とも二室とり、北は土間、南は現在畳敷の居室とする。伝承から笠松陣屋にあった代官屋敷門を移築したとされ、表通りの景観を形成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013547"},{"id":"00006843","register_sub_id":"101","register_pk":"107825","name":"伊藤家住宅収蔵庫","kana":"いとうけじゅうたくしゅうぞうこ","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"low","period":"大正","pref":"岐阜県","address":null,"lat":null,"lng":null,"geo_status":"missing","era":"大正15","year":1926,"year_source":"db","year_min":1926,"year_max":1926,"year_label":null,"structure":"鉄筋コンクリート造2階地下1階建、建築面積83㎡、塔屋付","structure_material":"鉄筋コンクリート造2階地下1階建","registered":"2008.03.07(平成20.03.07)","register_no":"21 － 0156","desc":"主屋の北西後方に建つ。 正面７．４ｍ奥行１１ｍ、鉄筋コンクリート造、地上２階、地下１階、屋根は陸屋根で、塔屋を設ける。外壁は石積風に目地を切り、上部に歯飾り付のコーニスをまわしてアクセントとする。直線的意匠で構成したモダンな外観の収蔵庫。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006843"},{"id":"00006842","register_sub_id":"101","register_pk":"107824","name":"伊藤家住宅主屋","kana":"いとうけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"岐阜県","address":null,"lat":null,"lng":null,"geo_status":"missing","era":"明治13／平成18改修","year":1880,"year_source":"db","year_min":1880,"year_max":1880,"year_label":null,"structure":"木造2階建、瓦葺、建築面積271㎡","structure_material":"木造2階建","registered":"2008.03.07(平成20.03.07)","register_no":"21 － 0155","desc":"揖斐川西側の敷地の中央、石造基壇上に南面して建つ。建築面積２７１㎡、木造２階建、寄棟造桟瓦葺。六間取の居室部の前後に廊下を張り出した平面とし、１０畳の座敷にはトコを設ける。水害対策のため高く基壇を造る、地方的特徴を示す大型の住宅。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006842"},{"id":"00006657","register_sub_id":"101","register_pk":"107640","name":"石徹白家住宅主屋","kana":"いとしろけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"岐阜県","address":"岐阜県郡上市白鳥町石徹白第4号字森前42","lat":35.99012974,"lng":136.76817451,"geo_status":"db","era":"明治25","year":1892,"year_source":"db","year_min":1892,"year_max":1892,"year_label":null,"structure":"木造2階建、鉄板葺、建築面積158㎡","structure_material":"木造2階建","registered":"2007.12.05(平成19.12.05)","register_no":"21 － 0154","desc":"畑に囲まれた敷地に建ち、東面に融雪池を控える。桁行８間梁間４間、木造２階建、切妻造鉄板葺。石徹白地区は白山信仰に関する御師の家が点在し、当家もその一つであり、２階には礼拝のための設えを持ったゴシンゼンノマなどの部屋を配する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006657"},{"id":"00007993","register_sub_id":"101","register_pk":"128825","name":"今井家住宅主屋","kana":"いまいけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"岐阜県","address":"岐阜県中津川市馬籠3909","lat":35.53574011,"lng":137.58322046,"geo_status":"db","era":"明治前期／昭和中期・昭和後期改修","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"木造平屋建、鉄板葺、建築面積197㎡","structure_material":"木造平屋建","registered":"2010.01.15(平成22.01.15)","register_no":"21-0172","desc":"峠集落の中山道沿いに西面して建つ。桁行１５ｍ梁間１３ｍの木造つし２階建、切妻造鉄板葺。当初は牛小屋を設けた通りニワを南に、ミセなどの六間取の床上部を北に配する。正面には平格子や出格子を嵌め、駒繋の環金具を残し、街道沿いの歴史的佇まいを伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007993"},{"id":"00006196","register_sub_id":"101","register_pk":"107180","name":"今尾家住宅表門及び塀","kana":"いまおけじゅうたくおもてもんおよびへい","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"明治","pref":"岐阜県","address":"岐阜県各務原市那加新加納町2126","lat":35.39766614,"lng":136.82360751,"geo_status":"db","era":"明治後期・大正期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"表門 木造、瓦葺、間口2.0m、潜戸付、塀 木造、瓦葺、延長35m","structure_material":"表門 木造","registered":"2007.05.15(平成19.05.15)","register_no":"21 － 0118","desc":"敷地南側に建つ桟瓦葺の薬医門。扉は観音開き。両脇に潜戸を付ける。各潜戸から塀が折曲りで東西に延び，東は米蔵に，西は南西隅から北へ折れて離れに接続。塀は延長３４．５ｍで，丸石積の基礎，外側は杉板張の上部を白漆喰塗とし，柱間２間おきに窓を設ける。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006196"},{"id":"00006194","register_sub_id":"101","register_pk":"107178","name":"今尾家住宅米蔵","kana":"いまおけじゅうたくこめぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"大正","pref":"岐阜県","address":"岐阜県各務原市那加新加納町2126","lat":35.397701,"lng":136.823807,"geo_status":"db","era":"大正期","year":1919,"year_source":"estimated","year_min":1912,"year_max":1926,"year_label":"大正期","structure":"土蔵造2階建、瓦葺、建築面積30㎡","structure_material":"土蔵造2階建","registered":"2007.05.15(平成19.05.15)","register_no":"21 － 0117","desc":"敷地南東隅に西面して建つ。梁間２間，桁行３間規模の土蔵造２階建，切妻造，桟瓦葺とする。西面に差掛をかける。丸石積の基礎とし，外壁は西面を人造石洗出仕上げ，他３面を杉板張とし，上部を漆喰で塗り，軒に鉢巻を廻す。南側塀と連続した景観をなす。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006194"},{"id":"00006192","register_sub_id":"101","register_pk":"107176","name":"今尾家住宅主屋","kana":"いまおけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"岐阜県","address":"岐阜県各務原市那加新加納町2126","lat":35.39785,"lng":136.82349902,"geo_status":"db","era":"明治33","year":1900,"year_source":"db","year_min":1900,"year_max":1900,"year_label":null,"structure":"木造2階建、瓦葺、建築面積197㎡","structure_material":"木造2階建","registered":"2007.05.15(平成19.05.15)","register_no":"21 － 0115","desc":"敷地北西隅に南面して建つ。梁間４間，桁行１０間規模の木造２階建，入母屋造，桟瓦葺，平入で四周に下屋を廻す。規模が大きく，外壁を黒漆喰塗とし，棟を高く積んで降棟を置き，正面中央に大きな入母屋破風付の式台玄関を設ける等，重厚な外観を示す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006192"},{"id":"00006197","register_sub_id":"101","register_pk":"107181","name":"今尾家住宅中門及び塀","kana":"いまおけじゅうたくちゅうもんおよびへい","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"大正","pref":"岐阜県","address":"岐阜県各務原市那加新加納町2126","lat":35.39775014,"lng":136.82354073,"geo_status":"db","era":"大正期","year":1919,"year_source":"estimated","year_min":1912,"year_max":1926,"year_label":"大正期","structure":"中門 木造、瓦葺、間口1.2m、塀 木造、瓦葺、延長14m","structure_material":"中門 木造","registered":"2007.05.15(平成19.05.15)","register_no":"21 － 0119","desc":"主屋南側の離れ及び庭園を区切る。中門は桟瓦葺の腕木門で，小竹を上部にはめた桟唐戸を観音開きとする。塀は上部を黄土色の色壁仕上げ，下部を人造石洗出仕上げとし，柱間１間おきに飾り格子を入れた窓を設け，桟瓦葺とする。敷地景観を構成する重要な要素。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006197"},{"id":"00006193","register_sub_id":"101","register_pk":"107177","name":"今尾家住宅離れ","kana":"いまおけじゅうたくはなれ","category":"住宅","subcategory":"建築物","type_guess":"茶室・離れ","type_guess_confidence":"high","period":"大正","pref":"岐阜県","address":"岐阜県各務原市那加新加納町2126","lat":35.39772,"lng":136.82341,"geo_status":"db","era":"大正期","year":1919,"year_source":"estimated","year_min":1912,"year_max":1926,"year_label":"大正期","structure":"木造平屋建、瓦葺、建築面積68㎡","structure_material":"木造平屋建","registered":"2007.05.15(平成19.05.15)","register_no":"21 － 0116","desc":"敷地南西隅に東面して建つ木造平屋建。入母屋造，桟瓦葺で，四周に下屋を廻す。丸石を亀甲紋様に築いて基礎とし，外壁は杉板の押縁下見板張とし，上部を漆喰塗とする。東面に設ける庭園ならびに「茗竹居」の額を掲げる中門と共に風趣に富む敷地景観を形成。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006193"},{"id":"00006195","register_sub_id":"101","register_pk":"107179","name":"今尾家住宅薬師堂","kana":"いまおけじゅうたくやくしどう","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"岐阜県","address":"岐阜県各務原市那加新加納町2123-1","lat":35.39757899,"lng":136.823456,"geo_status":"db","era":"大正14","year":1925,"year_source":"db","year_min":1925,"year_max":1925,"year_label":null,"structure":"木造平屋建、檜皮葺、建築面積5.5㎡","structure_material":"木造平屋建","registered":"2007.05.15(平成19.05.15)","register_no":"21 － 0120","desc":"表門から道路を挟んで南側の敷地に東面して建つ。春日造，檜皮葺。１．２ｍ高の石垣の上に建ち，正面に石段を設ける。周囲に高欄を廻らし，正面扉に家紋の花菱を透彫にし，向拝垂木や組物の小口を胡粉で塗る。医家の家柄の格式を今に伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006195"},{"id":"00005454","register_sub_id":"101","register_pk":"106442","name":"梅田家住宅主屋","kana":"うめだけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"岐阜県","address":"岐阜県各務原市鵜沼西町1-530","lat":35.40460886,"lng":136.9356637,"geo_status":"db","era":"江戸後期","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造平屋建、瓦葺、建築面積166㎡","structure_material":"木造平屋建","registered":"2006.03.27(平成18.03.27)","register_no":"21 － 0082","desc":"市を東西に貫く旧中山道に北面して建つ。桁行６間，梁間５間，切妻造，平入とし，正面は，一階のほぼ東半に出格子を設け，２階には袖卯建をあげ，縦格子入りの窓を左右対称に配し，長押や柱を現す外観とする。旧鵜沼宿で唯一近世に遡る町家建築として貴重。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005454"},{"id":"00006046","register_sub_id":"101","register_pk":"107031","name":"梅田家住宅主屋","kana":"うめだけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"岐阜県","address":"岐阜県各務原市鵜沼西町1-529","lat":35.40463705,"lng":136.93550205,"geo_status":"db","era":"明治元","year":1868,"year_source":"db","year_min":1868,"year_max":1868,"year_label":null,"structure":"木造2階建、瓦葺、建築面積119㎡","structure_material":"木造2階建","registered":"2006.11.29(平成18.11.29)","register_no":"21 － 0106","desc":"旧中山道鵜沼宿の旧街道に北面して建つ切妻造桟瓦葺の平入町家である。桁行６間半，梁間４間で表裏に下屋が付く。１階中央入口の東に鉄格子窓，西に木格子窓を設け，２階は格子窓とする。内部は東に土間，西に８畳座敷と仏間を配す。宿場の趣を残す遺構。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006046"},{"id":"00005456","register_sub_id":"101","register_pk":"106444","name":"梅田家住宅土蔵","kana":"うめだけじゅうたくどぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"昭和前","pref":"岐阜県","address":"岐阜県各務原市鵜沼西町1-530","lat":35.40440041,"lng":136.93575945,"geo_status":"db","era":"昭和7","year":1932,"year_source":"db","year_min":1932,"year_max":1932,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積71㎡","structure_material":"土蔵造2階建","registered":"2006.03.27(平成18.03.27)","register_no":"21 － 0084","desc":"南北に細長い敷地の南東に，北面して建つ。桁行６間，梁間３間の２階建で，平入とし，北面に軒を深く張り出す。基礎は大型の石を亀甲積風に築き，東・西・南面は腰を簓子下見板張，北面は目地付モルタル洗出仕上げとする。敷地の角に建ち，屋敷構を整える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005456"},{"id":"00005986","register_sub_id":"101","register_pk":"106971","name":"梅田家住宅離れ","kana":"うめだけじゅうたくはなれ","category":"住宅","subcategory":"建築物","type_guess":"茶室・離れ","type_guess_confidence":"high","period":"明治","pref":"岐阜県","address":"岐阜県各務原市鵜沼西町1-529","lat":35.40441766,"lng":136.93550205,"geo_status":"db","era":"明治元","year":1868,"year_source":"db","year_min":1868,"year_max":1868,"year_label":null,"structure":"木造2階一部平屋建、瓦葺、建築面積107㎡","structure_material":"木造2階一部平屋建","registered":"2006.11.29(平成18.11.29)","register_no":"21 － 0107","desc":"敷地の背面側道路に面する。桁行６間半，梁間３間の切妻造２階建である。西２間が２階建土蔵で，１階中央が門，東は居室で入母屋造平屋建の座敷を突出して手摺りを巡らす。２階は門上部も居室として８畳２室等を配す。特異な平面を持ち，特色ある外観を呈す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005986"},{"id":"00005455","register_sub_id":"101","register_pk":"106443","name":"梅田家住宅離れ","kana":"うめだけじゅうたくはなれ","category":"住宅","subcategory":"建築物","type_guess":"茶室・離れ","type_guess_confidence":"high","period":"昭和前","pref":"岐阜県","address":"岐阜県各務原市鵜沼西町1-530","lat":35.40459876,"lng":136.93581235,"geo_status":"db","era":"昭和10頃","year":1935,"year_source":"db","year_min":1935,"year_max":1935,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積97㎡","structure_material":"木造平屋建","registered":"2006.03.27(平成18.03.27)","register_no":"21 － 0083","desc":"主屋の東に接続する。北東隅に茶室を配するＬ字形平面の木造平屋建で，軒桁には化粧丸太を用いる。中庭に面して，曇りガラスと透明ガラスを交互に嵌めた欄間を配し，廊下の西南隅には円窓を設ける。旧街道に向けて２つの入母屋破風を見せる特色ある外観。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005455"},{"id":"00013115","register_sub_id":"101","register_pk":"368273","name":"塩屋家住宅主屋","kana":"えんやけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"岐阜県","address":"岐阜県飛騨市古川町信包字殿野1398","lat":36.253875,"lng":137.12726389,"geo_status":"db","era":"明治前期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"木造2階建、金属板葺、建築面積292㎡","structure_material":"木造2階建","registered":"2019.12.05(令和1.12.05)","register_no":"21 － 0281","desc":"往還の分岐点に東面して建つ。切妻造平入の両妻に下屋を設け、全体が真壁で柱・貫などを現す。南側が土間で広い厩をもち、床上部は三列構成の中列に仏間、上列に座敷二室を並べる。土間に長大な梁を架すなど内外とも飛騨地方の伝統形式をよく示す大規模民家。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013115"},{"id":"00013116","register_sub_id":"101","register_pk":"368274","name":"塩屋家住宅土蔵","kana":"えんやけじゅうたくどぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"岐阜県","address":"岐阜県飛騨市古川町信包字殿野1398","lat":36.25398611,"lng":137.12748611,"geo_status":"db","era":"明治前期／昭和30年頃移築","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"土蔵造2階建、金属板葺、建築面積70㎡","structure_material":"土蔵造2階建","registered":"2019.12.05(令和1.12.05)","register_no":"21 － 0282","desc":"主屋東側に東西棟で建つ土蔵造二階建の家財蔵。北面に増築した板間と一体に大きく切妻造鉄板葺の屋根を架け、南正面にも下屋を設ける。土蔵は外壁漆喰塗で下半を人造石洗出仕上とし、開口に重厚な土戸を開く。旧道の三叉路沿いに建ち、集落景観に寄与する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013116"},{"id":"00012905","register_sub_id":"101","register_pk":"368008","name":"大坪酒造店別邸","kana":"おおつぼしゅぞうてんべってい","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"岐阜県","address":"岐阜県飛騨市神岡町朝浦字八幡腰515","lat":36.32981667,"lng":137.29917222,"geo_status":"db","era":"大正前期","year":1917,"year_source":"estimated","year_min":1912,"year_max":1918,"year_label":"大正前期","structure":"木造平屋建、金属板葺、建築面積117㎡","structure_material":"木造平屋建","registered":"2019.09.10(令和1.09.10)","register_no":"21 － 280","desc":"旧神岡町中心部にある酒造所奥の高台に建つ。主屋と上座敷棟を対角に配し、十字形平面の縁でつなぐ特異な形式をもつ。両棟とも数寄屋意匠の座敷飾を備え、主座敷は床と床脇の間に円窓、琵琶棚脇に平書院風に下地窓を穿つ。開放的かつ繊細なつくりの離れ座敷。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012905"},{"id":"00014605","register_sub_id":"101","register_pk":"515147","name":"岡本家住宅茶室","kana":"おかもとけじゅうたくちゃしつ","category":"住宅","subcategory":"建築物","type_guess":"茶室・離れ","type_guess_confidence":"high","period":"大正","pref":"岐阜県","address":"岐阜県岐阜市金屋町1丁目10","lat":35.42285278,"lng":136.76335278,"geo_status":"db","era":"大正2年頃／令和2年改修","year":1913,"year_source":"db","year_min":1913,"year_max":1913,"year_label":null,"structure":"木造平屋建、瓦葺一部檜皮葺及びこけら葺、建築面積20㎡","structure_material":"木造平屋建","registered":"2023.08.07(令和5.08.07)","register_no":"21 - 0298","desc":"岐阜市の金屋町に位置する旧家の茶室。主屋の北妻に接続する切妻造妻入桟瓦葺で北面に檜皮葺、西面にこけら葺下屋を付す。内部は南半をカッテ、北半を水屋と茶室とし、茶室は二畳台目中板入りで南東に床を構える。屋根に変化を付けた丁寧な造りの茶室。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014605"},{"id":"00014606","register_sub_id":"101","register_pk":"515148","name":"岡本家住宅待合","kana":"おかもとけじゅうたくまちあい","category":"住宅","subcategory":"その他工作物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"岐阜県","address":"岐阜県岐阜市金屋町1丁目10","lat":35.42288333,"lng":136.76344722,"geo_status":"db","era":"大正2年頃","year":1913,"year_source":"db","year_min":1913,"year_max":1913,"year_label":null,"structure":"木造、杉皮葺、面積3.8㎡","structure_material":"木造","registered":"2023.08.07(令和5.08.07)","register_no":"21 - 0299","desc":"茶室の北東に西面する待合で敷地東辺に沿って建つ。平屋建の杉皮葺片流で、待合の南側に落棟の雪隠を付属する。軸部は主として丸太を用い、軒は小丸太の垂木。西面南半の出入口以外を土壁とし西壁に円窓の下地窓を開ける。旧家の落着いた露地を構成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014606"},{"id":"00008115","register_sub_id":"101","register_pk":"132513","name":"奥村家住宅主屋","kana":"おくむらけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和前","pref":"岐阜県","address":"岐阜県各務原市大佐野町2-183","lat":35.38399472,"lng":136.83963684,"geo_status":"db","era":"昭和3年","year":1928,"year_source":"db","year_min":1928,"year_max":1928,"year_label":null,"structure":"木造2階建、瓦葺、建築面積146㎡","structure_material":"木造2階建","registered":"2010.04.28(平成22.04.28)","register_no":"21 － 0180","desc":"南面して建つ桁行１７ｍ梁間８．６ｍの木造２階建で、入母屋造桟瓦葺とし、四周に下屋をまわす。床上部は前後二列に各三室を配し、仏間にはトコや付書院を構える。南北面は引違い戸をたて開放的に扱い、東西面は真壁造の黒漆喰壁とし落ち着きのある外観とする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008115"},{"id":"00006527","register_sub_id":"101","register_pk":"107510","name":"尾関幸一家住宅主屋","kana":"おぜきこういちけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"大正","pref":"岐阜県","address":"岐阜県各務原市川島松倉町1437","lat":35.366394,"lng":136.832397,"geo_status":"db","era":"大正4","year":1915,"year_source":"db","year_min":1915,"year_max":1915,"year_label":null,"structure":"木造2階建、瓦葺、建築面積111㎡","structure_material":"木造2階建","registered":"2007.07.31(平成19.07.31)","register_no":"21 － 0127","desc":"木曽川の中洲に位置し，県道に東面する屋敷地の北西部に東西棟で建つ。桁行１２．２ｍ，梁行１０．４ｍ規模，切妻造，桟瓦葺の木造２階建で，西，南，北３面に下屋を廻す。東方に土間，西方に居室部を配し，２階を蚕室とする。当地域の養蚕農家の一例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006527"},{"id":"00006529","register_sub_id":"101","register_pk":"107512","name":"尾関幸一家住宅納屋","kana":"おぜきこういちけじゅうたくなや","category":"住宅","subcategory":"建築物","type_guess":"茶室・離れ","type_guess_confidence":"high","period":"大正","pref":"岐阜県","address":"岐阜県各務原市川島松倉町1437","lat":35.36634953,"lng":136.832565,"geo_status":"db","era":"大正4","year":1915,"year_source":"db","year_min":1915,"year_max":1915,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積33㎡","structure_material":"木造平屋建","registered":"2007.07.31(平成19.07.31)","register_no":"21 － 0129","desc":"主屋の東方に南北棟で建つ。桁行１４．１ｍ，梁行２．７ｍ，切妻造，桟瓦葺の木造平屋建で，北方は物置，南方は井戸・流し・浴室等からなり，その間の落棟部に外便所を設ける。外部は漆喰塗の真壁造で，腰高く板を張る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006529"},{"id":"00006528","register_sub_id":"101","register_pk":"107511","name":"尾関幸一家住宅離れ","kana":"おぜきこういちけじゅうたくはなれ","category":"住宅","subcategory":"建築物","type_guess":"茶室・離れ","type_guess_confidence":"high","period":"昭和前","pref":"岐阜県","address":"岐阜県各務原市川島松倉町1437","lat":35.366302,"lng":136.832306,"geo_status":"db","era":"昭和16","year":1941,"year_source":"db","year_min":1941,"year_max":1941,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積68㎡、渡廊下付","structure_material":"木造平屋建","registered":"2007.07.31(平成19.07.31)","register_no":"21 － 0128","desc":"主屋の南西方に南北棟で建ち，渡廊下で主屋と繋げる。桁行９．６ｍ，梁行５．７ｍ，入母屋造，桟瓦葺の木造平屋建で，西以外の３面に下屋を廻す。内部は８畳２室を並べ，南方座敷には西面に各１間の床と棚を備える。吟味された材料による上質なつくりの離れ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006528"},{"id":"00004966","register_sub_id":"101","register_pk":"105956","name":"葛西家住宅主屋","kana":"かさいけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"岐阜県","address":"岐阜県岐阜市敷島町九丁目82","lat":35.40696707,"lng":136.73037462,"geo_status":"db","era":"明治28","year":1895,"year_source":"db","year_min":1895,"year_max":1895,"year_label":null,"structure":"木造2階建、瓦葺、建築面積255㎡","structure_material":"木造2階建","registered":"2005.11.10(平成17.11.10)","register_no":"21 － 0059","desc":"市郊外にある大規模民家。南面して建つ切妻造２階建，平入で，４面に下屋を廻し，南面中央に入母屋造の玄関を突出し，桟瓦葺屋根とする。居室部は６間取に畳廊下を備えた平面で，全体に良材を用いた上質なつくりになり，随所に高い建築技術が発揮されている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004966"},{"id":"00004967","register_sub_id":"101","register_pk":"105957","name":"葛西家住宅長屋門","kana":"かさいけじゅうたくながやもん","category":"住宅","subcategory":"建築物","type_guess":"門","type_guess_confidence":"high","period":"明治","pref":"岐阜県","address":"岐阜県岐阜市敷島町九丁目82","lat":35.40674276,"lng":136.73040721,"geo_status":"db","era":"明治28頃","year":1895,"year_source":"db","year_min":1895,"year_max":1895,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積43㎡","structure_material":"木造平屋建","registered":"2005.11.10(平成17.11.10)","register_no":"21 － 0060","desc":"主屋の南方にある。東西棟の切妻造，桟瓦葺の長屋門で，桁行約１４ｍの規模をもつ。中央やや東寄りに門口を構え，東側を物置，西側を供部屋とする。南面は腰を押縁下見板張，開口部には板屋根付の出格子をつける。屋敷正面に相応しい豪壮な構えを呈している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004967"},{"id":"00006536","register_sub_id":"101","register_pk":"107519","name":"蒲酒造場仕込蔵二","kana":"かばしゅぞうじょうしこみぐらに","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"low","period":"明治","pref":"岐阜県","address":"岐阜県飛騨市古川町壱之町6-6","lat":36.23517778,"lng":137.18689132,"geo_status":"db","era":"明治39","year":1906,"year_source":"db","year_min":1906,"year_max":1906,"year_label":null,"structure":"土蔵造2階建、鉄板葺、建築面積45㎡","structure_material":"土蔵造2階建","registered":"2007.07.31(平成19.07.31)","register_no":"21 － 0134","desc":"瀬戸川用水と大横丁の交差する屋敷地北西隅に南北棟で建つ。桁行４間半，梁間３間規模の２階建土蔵で，屋根は切妻造の置屋根とし，南側桁行１間半分は棟を高める。もと料亭の蔵で，内部天井の中心飾りなどに洋風意匠が採り入れられているのが特徴。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006536"},{"id":"00006534","register_sub_id":"101","register_pk":"107517","name":"蒲酒造場文庫蔵","kana":"かばしゅぞうじょうぶんこぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"岐阜県","address":"岐阜県飛騨市古川町壱之町6-6","lat":36.235046,"lng":137.187149,"geo_status":"db","era":"明治39","year":1906,"year_source":"db","year_min":1906,"year_max":1906,"year_label":null,"structure":"土蔵造2階建、鉄板葺、建築面積85㎡","structure_material":"土蔵造2階建","registered":"2007.07.31(平成19.07.31)","register_no":"21 － 0132","desc":"主屋の北方に位置し，屋敷地北側を流れる瀬戸川用水に沿って東西棟で建つ。桁行８間半，梁間３間規模，切妻造，鉄板葺の２階建土蔵で，１階西寄りに１間幅の通路をとり，北面に戸口を設ける。押縁下見板張に白漆喰塗の外観は用水沿いの酒蔵景観の一翼を担う。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006534"},{"id":"00010149","register_sub_id":"101","register_pk":"197982","name":"上の上田屋上田家住宅主屋","kana":"かみのうえだやうえだけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"岐阜県","address":"岐阜県中津川市落合字落合町831","lat":35.510976,"lng":137.531727,"geo_status":"db","era":"明治前期／昭和初期・平成16改修","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"木造2階建一部地階付、瓦葺、建築面積200㎡","structure_material":"木造2階建一部地階付","registered":"2014.10.07(平成26.10.07)","register_no":"21 － 0230","desc":"中山道落合宿で街道に南面する。二階正面を出梁で前方に持出し、出格子をたてる。内部は東側を土間とし、土間の奥寄りは奥部屋の床下を経て背面の庭へと抜ける。床上部は、前寄りを表間とし、奥に居室や座敷を二列並べる。中山道宿役人の格式を伝える町家。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010149"},{"id":"00010151","register_sub_id":"101","register_pk":"197984","name":"上の上田屋上田家住宅土蔵","kana":"かみのうえだやうえだけじゅうたくどぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"岐阜県","address":"岐阜県中津川市落合字落合町831","lat":35.510907,"lng":137.53181,"geo_status":"db","era":"明治37","year":1904,"year_source":"db","year_min":1904,"year_max":1904,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積25㎡","structure_material":"土蔵造2階建","registered":"2014.10.07(平成26.10.07)","register_no":"21 － 0232","desc":"街道に面して主屋の東に南北棟で建つ。土蔵造二階建、切妻造桟瓦葺で、鉢巻を廻らし、入口を北面に開く。街道に面する南面は下半を海鼠壁、上半を黒漆喰塗とし、二階窓には土戸を開き、持送付きの瓦葺の庇を設ける。主屋とともに宿場町の景観を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010151"},{"id":"00010150","register_sub_id":"101","register_pk":"197983","name":"上の上田屋上田家住宅離れ","kana":"かみのうえだやうえだけじゅうたくはなれ","category":"住宅","subcategory":"建築物","type_guess":"茶室・離れ","type_guess_confidence":"high","period":"明治","pref":"岐阜県","address":"岐阜県中津川市落合字落合町831","lat":35.511016,"lng":137.531927,"geo_status":"db","era":"明治前期／大正期・昭和後期改修","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"木造平屋建地階付、瓦葺、建築面積41㎡","structure_material":"木造平屋建地階付","registered":"2014.10.07(平成26.10.07)","register_no":"21 － 0231","desc":"主屋の北東に接続し、庭に面して建つ木造平屋建。北側の新座敷は、敷地の傾斜を活かし床高を上げて庭を望み、トコとトコ脇を設ける。同室の北東面は開放的な造作とし、高欄付の縁を廻らせる。地階北側は大壁造の味噌蔵とする。瀟洒な佇まいの離れ座敷。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010150"},{"id":"00001606","register_sub_id":"101","register_pk":"102596","name":"上山家住宅北棟","kana":"かみやまけじゅうたくきたとう","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"岐阜県","address":"岐阜県多治見市上山町1-1","lat":35.3382,"lng":137.133453,"geo_status":"db","era":"昭和初期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和初期","structure":"木造平屋建、瓦葺、建築面積61㎡","structure_material":"木造平屋建","registered":"2000.04.28(平成12.04.28)","register_no":"21 － 0020","desc":"主屋の北に接続する木造，平屋建，桟瓦葺，南北棟の入母屋造建屋で，東・北・西の三面に下屋庇を付けてつし２階風の外観を造る。主屋・洋館とともに邸宅主体部の主要な構成要素で，東半は厨房に充てられており，東屋根上に切妻の換気窓を設ける。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001606"},{"id":"00001609","register_sub_id":"101","register_pk":"102599","name":"上山家住宅北物置","kana":"かみやまけじゅうたくきたものおき","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"岐阜県","address":"岐阜県多治見市上山町1-1","lat":35.338287,"lng":137.13350542,"geo_status":"db","era":"昭和初期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和初期","structure":"木造平屋建、瓦葺、建築面積29㎡","structure_material":"木造平屋建","registered":"2000.04.28(平成12.04.28)","register_no":"21 － 0023","desc":"２階建土蔵の東方，主屋の北東方に位置する。邸宅の維持管理や調理等に当たる使用人の住居とされる。木造，平屋建，桟瓦葺，東西棟，切妻屋根の丁寧な造りの真壁造建屋で，南面と東面の２面に土庇を設けて東妻側の便所を納める。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001609"},{"id":"00001604","register_sub_id":"101","register_pk":"102594","name":"上山家住宅主屋","kana":"かみやまけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"大正","pref":"岐阜県","address":"岐阜県多治見市上山町1-1","lat":35.33810417,"lng":137.13337152,"geo_status":"db","era":"大正末期","year":1922,"year_source":"estimated","year_min":1919,"year_max":1926,"year_label":"大正末期","structure":"木造平屋建、瓦葺、建築面積142㎡","structure_material":"木造平屋建","registered":"2000.04.28(平成12.04.28)","register_no":"21 － 0018","desc":"佐藤化粧煉瓦工場（現上山製陶株式会社）創業者の邸宅で，土岐川右岸沿いの敷地に南面して建つ。木造，平屋建，桟瓦葺，片寄棟造で，南東端に入母屋破風の玄関を設け，南面に縁側，南西端に月見台を張り出す。縁側庇をスレート葺とするなど端正な造りになる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001604"},{"id":"00001608","register_sub_id":"101","register_pk":"102598","name":"上山家住宅倉庫","kana":"かみやまけじゅうたくそうこ","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"low","period":"大正","pref":"岐阜県","address":"岐阜県多治見市上山町1-1","lat":35.33822855,"lng":137.13326286,"geo_status":"db","era":"大正末期","year":1922,"year_source":"estimated","year_min":1919,"year_max":1926,"year_label":"大正末期","structure":"土蔵造2階建、瓦葺、建築面積40㎡","structure_material":"土蔵造2階建","registered":"2000.04.28(平成12.04.28)","register_no":"21 － 0022","desc":"洋館の北方に建つ２階建，桟瓦葺，東西棟，切妻屋根，平入の土蔵で，南面に土庇を設けて蔵前とする。基礎は花崗石の三段積みで，階下を海鼠壁，階上を黒漆喰塗とし，妻面に重厚な観音扉と瓦葺の庇を付けた上質な造りになる蔵である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001608"},{"id":"00001610","register_sub_id":"101","register_pk":"102600","name":"上山家住宅西物置","kana":"かみやまけじゅうたくにしものおき","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"岐阜県","address":"岐阜県多治見市上山町1-1","lat":35.33814204,"lng":137.13323114,"geo_status":"db","era":"大正末期","year":1922,"year_source":"estimated","year_min":1919,"year_max":1926,"year_label":"大正末期","structure":"木造平屋建、瓦葺、建築面積17㎡","structure_material":"木造平屋建","registered":"2000.04.28(平成12.04.28)","register_no":"21 － 0024","desc":"洋館の北西方，土蔵の南西方に建つ。木造，平屋建，桟瓦葺，南北棟の片入母屋造建屋で，もと書生部屋とされる。平側は真壁造の簡素な造りであるが，南妻面に玄関を設け，縦板張とするなど洋館玄関を意識した造りとしている点に特徴がある。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001610"},{"id":"00001607","register_sub_id":"101","register_pk":"102597","name":"上山家住宅東棟","kana":"かみやまけじゅうたくひがしとう","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"岐阜県","address":"岐阜県多治見市上山町1-1","lat":35.3381319,"lng":137.13364645,"geo_status":"db","era":"大正末期","year":1922,"year_source":"estimated","year_min":1919,"year_max":1926,"year_label":"大正末期","structure":"木造平屋建、瓦葺、建築面積58㎡","structure_material":"木造平屋建","registered":"2000.04.28(平成12.04.28)","register_no":"21 － 0021","desc":"主屋の東に渡り廊下で接続する木造，平屋建，桟瓦葺，東西棟，入母屋造の離れ風建屋。東面は腰を縦板張，上部を真壁造とした和風表現をとるが，南面にはテラス，西南端にはベイウィンドー付洋室を設けてタイル張とするなど洋館に合わせた意匠とする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001607"},{"id":"00001605","register_sub_id":"101","register_pk":"102595","name":"上山家住宅洋館","kana":"かみやまけじゅうたくようかん","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"岐阜県","address":"岐阜県多治見市上山町1-1","lat":35.33810493,"lng":137.13346893,"geo_status":"db","era":"大正末期","year":1922,"year_source":"estimated","year_min":1919,"year_max":1926,"year_label":"大正末期","structure":"木造2階建、スレート葺、建築面積70㎡","structure_material":"木造2階建","registered":"2000.04.28(平成12.04.28)","register_no":"21 － 0019","desc":"主屋の西に接続する木造２階建の洋館で，西面に玄関を設ける。基礎を石張，階下の窓廻りと腰の高い位置までをタイル張とし，それ以上をドイツ壁風の仕上とする。銅板を縁に廻したスレート葺の切妻屋根に特徴があり，ランドマークにもなっている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001605"},{"id":"00001613","register_sub_id":"101","register_pk":"102603","name":"河合家住宅主屋","kana":"かわいけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"岐阜県","address":"岐阜県郡上市八幡町市島1545","lat":35.79388097,"lng":137.01465038,"geo_status":"db","era":"文化2","year":1805,"year_source":"db","year_min":1805,"year_max":1805,"year_label":null,"structure":"木造2階建、瓦葺、建築面積291㎡","structure_material":"木造2階建","registered":"2000.04.28(平成12.04.28)","register_no":"21 － 0027","desc":"地区の庄屋を務めた家柄の居宅で，桁行約１２間半，梁間約６間半の規模を有し，東部を土間とし厩を南面に張り出す。２階は養蚕を考慮した開放的な造りとする。南面の下屋庇の持送りには刳型装飾が施され，特に意が凝らされている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001613"},{"id":"00001615","register_sub_id":"101","register_pk":"102605","name":"河合家住宅西土蔵","kana":"かわいけじゅうたくにしどぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"岐阜県","address":"岐阜県郡上市八幡町市島1545","lat":35.79389529,"lng":137.01438092,"geo_status":"db","era":"明治18","year":1885,"year_source":"db","year_min":1885,"year_max":1885,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積36㎡","structure_material":"土蔵造2階建","registered":"2000.04.28(平成12.04.28)","register_no":"21 － 0029","desc":"主屋の西南方に味噌蔵と並んで建つ。南北棟，瓦葺，置屋根形式の２階建土蔵で，もとは板葺であった。桁行３間，梁間３間の規模を有し，東面の平側に庇を設けて蔵前とする。東面を海鼠壁，まぐさに装飾を施すなど東土蔵とは意匠を違えている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001615"},{"id":"00001614","register_sub_id":"101","register_pk":"102604","name":"河合家住宅東土蔵","kana":"かわいけじゅうたくひがしどぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"江戸","pref":"岐阜県","address":"岐阜県郡上市八幡町市島1545","lat":35.79367158,"lng":137.01461252,"geo_status":"db","era":"文政7","year":1824,"year_source":"db","year_min":1824,"year_max":1824,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積38㎡","structure_material":"土蔵造2階建","registered":"2000.04.28(平成12.04.28)","register_no":"21 － 0028","desc":"主屋の東南方，雪隠と長屋との間に建つ２階建，瓦葺，置屋根形式の土蔵。桁行３間半，梁間２間半の規模で，西面の平側に庇を差し出して蔵前とする。腰を板張りとした標準的な造りの土蔵で，屋敷構の一構成要素となる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001614"},{"id":"00009280","register_sub_id":"101","register_pk":"194073","name":"河合家別邸主屋","kana":"かわいけべっていしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和前","pref":"岐阜県","address":"岐阜県飛騨市古川町壱之町5-16","lat":36.2347568,"lng":137.18748789,"geo_status":"db","era":"昭和16年頃","year":1941,"year_source":"db","year_min":1941,"year_max":1941,"year_label":null,"structure":"木造平屋一部2階建、鉄板葺、建築面積173㎡","structure_material":"木造平屋一部2階建","registered":"2012.08.13(平成24.08.13)","register_no":"21 － 0201","desc":"敷地北側に建ち、建築面積一七三メートル。平面は土蔵を囲みＨ字形を呈し、北東・南西部は二階建切妻造、他は平屋建入母屋造。南東側に入母屋造の玄関を構える。南西部は南と東面に下屋を張出して縁を設け、窓を開ける。前庭の眺望に配慮した上質な数寄屋造。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009280"},{"id":"00009281","register_sub_id":"101","register_pk":"194074","name":"河合家別邸土蔵","kana":"かわいけべっていどぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"岐阜県","address":"岐阜県飛騨市古川町壱之町5-16","lat":36.23484437,"lng":137.18756784,"geo_status":"db","era":"明治中期","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"土蔵造2階建、鉄板葺、建築面積40㎡","structure_material":"土蔵造2階建","registered":"2012.08.13(平成24.08.13)","register_no":"21 － 0202","desc":"敷地北側中央に東西棟で建つ。桁行梁行とも六・四メートル、土蔵造二階建、切妻造、置屋根式の鉄板葺である。南面の主屋廊下側に戸口を開き、内側上部に黒漆喰で家紋をあしらった扉を吊る。小屋組は和小屋とし。主屋と一体となって良好な町家空間を醸す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009281"},{"id":"00009282","register_sub_id":"101","register_pk":"194075","name":"河合家別邸門及び塀","kana":"かわいけべっていもんおよびへい","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"昭和前","pref":"岐阜県","address":"岐阜県飛騨市古川町壱之町5-16","lat":36.23463307,"lng":137.18741365,"geo_status":"db","era":"昭和16年頃","year":1941,"year_source":"db","year_min":1941,"year_max":1941,"year_label":null,"structure":"門 銅板葺、間口2.9m 板塀 銅板葺、総延長41m","structure_material":"門 銅板葺","registered":"2012.08.13(平成24.08.13)","register_no":"21 － 0203","desc":"敷地南面の中央東寄りに、通りから後退して門を開き、左右に折曲がりの塀を延ばす。門は一間腕木門、切妻造鉄板葺で、土壁に格子目の欄間を開ける。塀は腰高く竪板張とし、土塗りの小壁に窓を穿つ。落ち着いた雰囲気を醸し町並みの景観に寄与している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009282"},{"id":"00013545","register_sub_id":"101","register_pk":"504912","name":"旧青木家住宅（エグゼクス・ガーデン）表門","kana":"きゅうあおきけじゅうたく（えぐぜくす・がーでん）おもてもん","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"明治","pref":"岐阜県","address":"岐阜県岐阜市大字日置江字屋敷前畑343-1","lat":35.37323611,"lng":136.70034167,"geo_status":"db","era":"明治2年","year":1869,"year_source":"db","year_min":1869,"year_max":1869,"year_label":null,"structure":"木造、瓦葺、間口2.9m","structure_material":"木造","registered":"2021.02.04(令和3.02.04)","register_no":"21 － 0283","desc":"敷地の南辺中央、堀に架かる橋に面した一間薬医門で切妻造の桟瓦葺とする。桟瓦葺の袖塀を東西に延ばし、西に潜戸を設ける。門柱は見付幅の広い長方形断面で成の高い冠木を受ける。控柱は内法高の桁行梁で繋ぎ、棟木は束立とする。木太く簡明な構造である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013545"},{"id":"00008125","register_sub_id":"101","register_pk":"132523","name":"旧岩崎家住宅主屋","kana":"きゅういわさきけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"岐阜県","address":"岐阜県下呂市森字柿ヶ平2369","lat":35.80869821,"lng":137.24999278,"geo_status":"db","era":"江戸中期／昭和43年移築","year":1735,"year_source":"estimated","year_min":1661,"year_max":1751,"year_label":"江戸中期","structure":"木造平屋建、茅葺、建築面積144㎡","structure_material":"木造平屋建","registered":"2010.04.28(平成22.04.28)","register_no":"21 － 0190","desc":"桁行１５ｍ梁間８．２ｍ規模、切妻造妻入茅葺。南面して建ち、南に土間を設け、北半部をデイやオエからなる田の字型四間取とし、オマエの背後に仏間を下屋で張り出す。正面に茅葺が葺きまわされ、入母屋風に復原できるなど、五箇山地方合掌造民家の古例である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008125"},{"id":"00012544","register_sub_id":"101","register_pk":"367839","name":"旧北岡田家住宅北納屋","kana":"きゅうきたおかだけじゅうたくきたなや","category":"住宅","subcategory":"建築物","type_guess":"茶室・離れ","type_guess_confidence":"high","period":"昭和前","pref":"岐阜県","address":"岐阜県揖斐郡大野町大字相羽字村通282-1他","lat":35.458008,"lng":136.639664,"geo_status":"geocoded","era":"昭和3年","year":1928,"year_source":"db","year_min":1928,"year_max":1928,"year_label":null,"structure":"木造2階建、瓦葺、建築面積98㎡","structure_material":"木造2階建","registered":"2018.11.02(平成30.11.02)","register_no":"21 － 0269","desc":"主屋後方の敷地北面に建つ。東西棟の切妻造桟瓦葺で南面に下屋を通す。真壁造で外壁は漆喰塗の腰縦板張、内部は漆喰塗である。西室に板敷の穀物部屋、東室に土間の漬物部屋と馬屋を設ける。大規模農家の生活の様相を知る上で欠かせない附属建物である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012544"},{"id":"00012541","register_sub_id":"101","register_pk":"367836","name":"旧北岡田家住宅米蔵","kana":"きゅうきたおかだけじゅうたくこめぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"岐阜県","address":"岐阜県揖斐郡大野町大字相羽字村通282-1他","lat":35.458008,"lng":136.639664,"geo_status":"geocoded","era":"明治37年／大正後期増築","year":1904,"year_source":"db","year_min":1904,"year_max":1904,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積83㎡","structure_material":"土蔵造2階建","registered":"2018.11.02(平成30.11.02)","register_no":"21 － 0266","desc":"敷地東南隅に東西棟で建つ。土蔵造二階建、切妻造桟瓦葺で、北面に扉口を設けて前室をつくる。外壁は漆喰塗の腰縦板張とし、軒裏まで塗込める。明治29年の洪水の教訓から高い玉石積の石垣上にあって、集落の道路景観において際立った存在感を示している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012541"},{"id":"00009283","register_sub_id":"101","register_pk":"194076","name":"旧北岡田家住宅主屋","kana":"きゅうきたおかだけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"大正","pref":"岐阜県","address":"岐阜県揖斐郡大野町大字相羽字村通282","lat":35.45511839,"lng":136.63478315,"geo_status":"db","era":"大正5年","year":1916,"year_source":"db","year_min":1916,"year_max":1916,"year_label":null,"structure":"木造2階建、瓦葺、建築面積432㎡","structure_material":"木造2階建","registered":"2012.08.13(平成24.08.13)","register_no":"21 － 0204","desc":"広大な敷地の中央に南面して建つ。建築面積四三二平方メートル。切妻造桟瓦葺で、深い下屋を廻す。正面東寄りに入母屋造の式台玄関を構える。西側には各一五畳の中の間と座敷が並び、入側を介して庭園を望む。上質な造作と豪壮な屋敷構えをもつ和風建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009283"},{"id":"00012542","register_sub_id":"101","register_pk":"367837","name":"旧北岡田家住宅道具蔵","kana":"きゅうきたおかだけじゅうたくどうぐぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"岐阜県","address":"岐阜県揖斐郡大野町大字相羽字村通282-1他","lat":35.458008,"lng":136.639664,"geo_status":"geocoded","era":"明治38年／昭和9年増築","year":1905,"year_source":"db","year_min":1905,"year_max":1905,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積137㎡、渡廊下付","structure_material":"土蔵造2階建","registered":"2018.11.02(平成30.11.02)","register_no":"21 － 0267","desc":"敷地西北隅に東西棟で建つ。東・西の二蔵に切妻造桟瓦葺の屋根を一体でかけ、南面に下屋を通す。内部は上下階とも板壁、小屋組は東蔵が和小屋、西蔵が登梁である。高い石垣上に建つ長大な蔵で、北面に整然と並ぶ庇付の窓が集落の道路景観を特徴づけている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012542"},{"id":"00012540","register_sub_id":"101","register_pk":"367835","name":"旧北岡田家住宅離れ","kana":"きゅうきたおかだけじゅうたくはなれ","category":"住宅","subcategory":"建築物","type_guess":"茶室・離れ","type_guess_confidence":"high","period":"明治","pref":"岐阜県","address":"岐阜県揖斐郡大野町大字相羽字村通282-1他","lat":35.458008,"lng":136.639664,"geo_status":"geocoded","era":"明治前期／昭和24年・同35年改修","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"木造平屋建、瓦葺、建築面積90㎡","structure_material":"木造平屋建","registered":"2018.11.02(平成30.11.02)","register_no":"21 － 0265","desc":"主屋西側に接続して建つ。東西棟の切妻造桟瓦葺で西南北三面に下屋を廻す。東端に4畳半の茶室を設け、西に二室を並べる。西端の座敷は奥行のある付書院を備え、南側に開放的な板間を設けるなど瀟洒で端正につくる。屋敷地内で濃尾地震以前に遡る唯一の遺構。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012540"},{"id":"00012543","register_sub_id":"101","register_pk":"367838","name":"旧北岡田家住宅東納屋","kana":"きゅうきたおかだけじゅうたくひがしなや","category":"住宅","subcategory":"建築物","type_guess":"茶室・離れ","type_guess_confidence":"high","period":"大正","pref":"岐阜県","address":"岐阜県揖斐郡大野町大字相羽字村通282-1他","lat":35.458008,"lng":136.639664,"geo_status":"geocoded","era":"大正後期","year":1922,"year_source":"estimated","year_min":1919,"year_max":1926,"year_label":"大正後期","structure":"木造2階建、瓦葺、建築面積116㎡","structure_material":"木造2階建","registered":"2018.11.02(平成30.11.02)","register_no":"21 － 0268","desc":"敷地東面にあって米蔵に接続して建つ。南北棟の切妻造桟瓦葺で東西北三面に下屋を廻す。真壁造の外側漆喰塗、内側荒壁で、内部は北から馬屋、大工部屋、味噌部屋を並べ、東面下屋を薪部屋とする。大規模農家の生活の様相を知る上で欠かせない附属建物である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012543"},{"id":"00008126","register_sub_id":"101","register_pk":"132524","name":"旧遠山家住宅板倉","kana":"きゅうとおやまけじゅうたくいたくら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"江戸","pref":"岐阜県","address":"岐阜県下呂市森字柿ヶ平2369","lat":35.80853513,"lng":137.24966418,"geo_status":"db","era":"文化7年（1810）／昭和37年移築","year":1810,"year_source":"db","year_min":1810,"year_max":1810,"year_label":null,"structure":"木造平屋建、茅葺、建築面積25㎡","structure_material":"木造平屋建","registered":"2010.04.28(平成22.04.28)","register_no":"21 － 0191","desc":"南北棟の切妻造茅葺、桁行５．５ｍ梁間４．５ｍ。床は板敷で、根太天井を張る。南寄り桁行１．８ｍを物置とし、東面に引違い戸をたて、北側を倉とする。倉の外壁は壁貫の両面に板を張る二重の板壁にして気密性を高める。建築年代が明確な点でも貴重な近世板倉。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008126"},{"id":"00005439","register_sub_id":"101","register_pk":"106427","name":"旧二村家住宅主屋","kana":"きゅうふたむらけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"岐阜県","address":"岐阜県高山市奥飛騨温泉郷福地字アリタ879-1","lat":36.22571431,"lng":137.53141887,"geo_status":"db","era":"天保9／平成17移築","year":1838,"year_source":"db","year_min":1838,"year_max":1838,"year_label":null,"structure":"木造2階建、鉄板葺、建築面積301㎡","structure_material":"木造2階建","registered":"2006.03.27(平成18.03.27)","register_no":"21 － 0067","desc":"市東部の温泉町福地を南北に流れる平湯川に面した敷地に西面して建つ。桁行２１ｍ，梁間１４ｍ，切妻造，鉄板葺とし，２階に木製出格子，１階に繊細な格子窓を嵌め込み，腰は押縁下見板張とする。檜材を主体とした良質な造りで，式台を備えた格式ある民家建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005439"},{"id":"00012538","register_sub_id":"101","register_pk":"367833","name":"旧宮川家住宅主屋","kana":"きゅうみやがわけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"岐阜県","address":"岐阜県関市小屋名1989-4","lat":35.478443,"lng":136.868347,"geo_status":"geocoded","era":"明治23年頃／昭和62年移築","year":1890,"year_source":"db","year_min":1890,"year_max":1890,"year_label":null,"structure":"木造平屋一部2階建、茅葺、建築面積132㎡","structure_material":"木造平屋一部2階建","registered":"2018.11.02(平成30.11.02)","register_no":"21 － 0263","desc":"徳山村から移築した農家主屋。入母屋造茅葺の屋根正面中央部を切欠いて庇を付す。内部は広間型で、イタノマの一部とネヤ上部に二階を設ける。半間毎の柱間を縦板張とした外壁や土間隅部に設けた紙漉き部屋など、美濃地方西部の山村農家の特徴をよく示す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012538"},{"id":"00008122","register_sub_id":"101","register_pk":"132520","name":"小島家住宅表門","kana":"こじまけじゅうたくおもてもん","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"昭和前","pref":"岐阜県","address":"岐阜県各務原市成清町2-76-2他","lat":35.38610992,"lng":136.82573099,"geo_status":"db","era":"昭和前期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和前期","structure":"木造、瓦葺、間口2.3m","structure_material":"木造","registered":"2010.04.28(平成22.04.28)","register_no":"21 － 0187","desc":"敷地の南辺東寄りに位置する。一間薬医門で、切妻造桟瓦葺。間口２．３ｍに五平の本柱を建て、控えは方柱とする。冠木を女梁と男梁で挟み、固める。妻は虹梁大瓶束で、蟇股風に作る。一軒疎垂木とし、拝みに鰭付猪目懸魚を飾る。屋敷正面に重厚感を与える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008122"},{"id":"00008116","register_sub_id":"101","register_pk":"132514","name":"小島家住宅主屋","kana":"こじまけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和前","pref":"岐阜県","address":"岐阜県各務原市大佐野町3-126","lat":35.38167102,"lng":136.83992766,"geo_status":"db","era":"昭和4年／昭和前期増築","year":1929,"year_source":"db","year_min":1929,"year_max":1929,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積202㎡","structure_material":"木造平屋建","registered":"2010.04.28(平成22.04.28)","register_no":"21 － 0181","desc":"敷地中央前寄りに位置し、背後に工場が建つ。木造平屋建。畳敷の廊下を東西に通す中廊下型平面で、南北に各三室を並べる。屋根は切妻造桟瓦葺とし、周囲に下屋庇をまわし、東面南寄りに宝形造の応接室、北寄りに半切妻造の寝室を付設して、独特の外観を造る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008116"},{"id":"00008119","register_sub_id":"101","register_pk":"132517","name":"小島家住宅主屋","kana":"こじまけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和前","pref":"岐阜県","address":"岐阜県各務原市成清町2-76-2他","lat":35.38628999,"lng":136.82569085,"geo_status":"db","era":"昭和前期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和前期","structure":"木造2階建、瓦葺、建築面積188㎡","structure_material":"木造2階建","registered":"2010.04.28(平成22.04.28)","register_no":"21 － 0184","desc":"敷地東寄りに南面して建つ、木造２階建。入母屋造桟瓦葺で、四周に下屋庇を付設する。東端にハタベヤ、西寄りに田の字型に四室を配し、その間に土間を設ける。西南隅は十三畳の座敷とし、優美な座敷飾りを構える。良材を使い、丁寧な仕上げになる近代和風住宅。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008119"},{"id":"00008123","register_sub_id":"101","register_pk":"132521","name":"小島家住宅外塀","kana":"こじまけじゅうたくそとべい","category":"住宅","subcategory":"その他工作物","type_guess":"塀","type_guess_confidence":"high","period":"昭和前","pref":"岐阜県","address":"岐阜県各務原市成清町2-76-2他","lat":35.38609952,"lng":136.82565442,"geo_status":"db","era":"昭和前期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和前期","structure":"土塀、瓦葺、延長18m","structure_material":"土塀","registered":"2010.04.28(平成22.04.28)","register_no":"21 － 0188","desc":"表門から東西に延び、折曲り総延長１８ｍを測る。自然石乱積基礎上の土塀で、腰モルタル洗い出しとし、その下端には緑色のタイルを貼る。上部は白漆喰仕上げで、表門際には片開の潜りを開け、要所に格子窓を穿ち、趣のある屋敷構えをつくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008123"},{"id":"00008124","register_sub_id":"101","register_pk":"132522","name":"小島家住宅中門及び庭塀","kana":"こじまけじゅうたくなかもんおよびにわべい","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"昭和前","pref":"岐阜県","address":"岐阜県各務原市成清町2-76-2他","lat":35.38616224,"lng":136.82570732,"geo_status":"db","era":"昭和前期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和前期","structure":"中門 木造、瓦葺、間口1.5m、庭塀 木造、銅板葺、延長7.1m","structure_material":"中門 木造","registered":"2010.04.28(平成22.04.28)","register_no":"21 － 0189","desc":"主屋南側の庭を画する。中門は南北中央に位置する、間口１．５ｍの腕木門。入母屋造桟瓦葺で軒先を銅板葺とする。軸部や垂木を丸太材とし、上部に欄間を飾る。庭塀は南北に延びる折曲り総延長７．１ｍ、銅板葺の板塀。数寄屋風意匠で品のある佇まいを見せる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008124"},{"id":"00008120","register_sub_id":"101","register_pk":"132518","name":"小島家住宅附属屋","kana":"こじまけじゅうたくふぞくや","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"岐阜県","address":"岐阜県各務原市成清町2-76-2他","lat":35.38618292,"lng":136.82577889,"geo_status":"db","era":"昭和前期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和前期","structure":"木造平屋建、瓦葺、建築面積22㎡","structure_material":"木造平屋建","registered":"2010.04.28(平成22.04.28)","register_no":"21 － 0185","desc":"主屋南面東端から南北に延びる。切妻造桟瓦葺とし、北半部は棟を一段下げる。桁行９．７ｍ梁間２．３ｍで、南端を井戸や洗い場、北寄りを便所、その間を風呂とする。白漆喰仕上げの真壁造で、外壁には腰板、内部にはタイルなどを貼る。軽快な意匠になる附属屋。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008120"},{"id":"00013548","register_sub_id":"101","register_pk":"504915","name":"後藤家住宅主屋","kana":"ごとうけじゅうたくおもや","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"岐阜県","address":"岐阜県岐阜市芥見一丁目48","lat":35.44974722,"lng":136.84025278,"geo_status":"db","era":"明治28年","year":1895,"year_source":"db","year_min":1895,"year_max":1895,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積118㎡","structure_material":"木造平屋建","registered":"2021.02.04(令和3.02.04)","register_no":"21 － 0286","desc":"郡上街道の西側に建つ切妻造の東西棟で四周の下屋とも桟瓦葺とする。南面東寄りが玄関で北に台所を配す。西の床上は二列六室で南から西へ縁を廻し、西端を続き間座敷とする。玄関南東に風呂が接続する。欄間や金具に意匠を凝らした有力商家の近代住宅。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013548"},{"id":"00013553","register_sub_id":"101","register_pk":"504920","name":"後藤家住宅地蔵覆屋","kana":"ごとうけじゅうたくじぞうおおいや","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"low","period":"明治","pref":"岐阜県","address":"岐阜県岐阜市芥見一丁目48","lat":35.44959444,"lng":136.84046667,"geo_status":"db","era":"明治前期／昭和40年移築","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"木造平屋建、瓦葺、建築面積0.4㎡","structure_material":"木造平屋建","registered":"2021.02.04(令和3.02.04)","register_no":"21 － 0291","desc":"敷地の東面南寄り、旧郵便局舎の南東に建つ切妻造妻入で桟瓦葺とする。上面を均した一石の上に土台を井桁に組み、角柱を立て正面に虹梁形の頭貫を架け斗組を据える。中備は蟇股である。正面は開放、側面は縦格子、背面は板壁とする。丁寧な造作の小祠である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013553"},{"id":"00013551","register_sub_id":"101","register_pk":"504918","name":"後藤家住宅土蔵","kana":"ごとうけじゅうたくどぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"江戸","pref":"岐阜県","address":"岐阜県岐阜市芥見一丁目48","lat":35.44956389,"lng":136.84022222,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"土蔵造2階建、瓦葺、建築面積40㎡","structure_material":"土蔵造2階建","registered":"2021.02.04(令和3.02.04)","register_no":"21 － 0289","desc":"主屋の南、旧郵便局舎の西に建つ東西棟の家財蔵で、切妻造の桟瓦葺である。北面の下屋の東妻に出入口を設ける。外壁は白漆喰塗で腰を波形鉄板張とする。軒裏と螻羽は漆喰で塗り込める。小屋組は太い牛梁に登梁を架ける。濃尾地震以前の景観を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013551"},{"id":"00013549","register_sub_id":"101","register_pk":"504916","name":"後藤家住宅離れ","kana":"ごとうけじゅうたくはなれ","category":"住宅","subcategory":"建築物","type_guess":"茶室・離れ","type_guess_confidence":"high","period":"大正","pref":"岐阜県","address":"岐阜県岐阜市芥見一丁目48","lat":35.44969167,"lng":136.84001667,"geo_status":"db","era":"大正前期／昭和45年移築","year":1917,"year_source":"estimated","year_min":1912,"year_max":1918,"year_label":"大正前期","structure":"木造平屋建、瓦葺、建築面積22㎡","structure_material":"木造平屋建","registered":"2021.02.04(令和3.02.04)","register_no":"21 － 0287","desc":"主屋の西方、庭を介して渡廊下で接続する南北棟である。切妻造の桟瓦葺で東面に鉄板葺の下屋の縁が付く。外壁は縦羽目板張である。南に八畳座敷、北に四畳半茶室と水屋を配す。網代と市松にした障子や波欄間形の無双窓など上品な数寄屋造作の離れ座敷。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013549"},{"id":"00013552","register_sub_id":"101","register_pk":"504919","name":"後藤家住宅門","kana":"ごとうけじゅうたくもん","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"昭和前","pref":"岐阜県","address":"岐阜県岐阜市芥見一丁目48","lat":35.4497,"lng":136.84041944,"geo_status":"db","era":"昭和12年","year":1937,"year_source":"db","year_min":1937,"year_max":1937,"year_label":null,"structure":"木造、瓦葺、間口1.9m","structure_material":"木造","registered":"2021.02.04(令和3.02.04)","register_no":"21 － 0290","desc":"敷地の東面中央、主屋と旧郵便局舎の間に建つ。一間薬医門で切妻造桟瓦葺とする。南北に袖塀がつく。門柱は角柱で冠木を受け、男梁下に小振りな女梁を添える。棟木は撥束で受ける。冠木下に二本溝の鴨居が残り、旧は引戸二枚を建込んだ。宅地正面の軽快な門。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013552"},{"id":"00009759","register_sub_id":"101","register_pk":"195588","name":"小林家住宅主屋","kana":"こばやしけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"岐阜県","address":"岐阜県不破郡垂井町字屋敷1268-1","lat":35.37152498,"lng":136.52372627,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造平屋一部2階建、瓦葺、建築面積151㎡","structure_material":"木造平屋一部2階建","registered":"2013.12.24(平成25.12.24)","register_no":"21 － 0218","desc":"中山道垂井宿に北面して建つ町家で、木造平屋一部二階建、切妻造桟瓦葺とし、正面に下屋を設ける。正面東側を戸口として土間を通し、西側に格子をたてる。二階正面は黒漆喰塗で虫籠窓を二所穿ち、袖うだつをあげる。中山道の宿場の面影を伝える近世の町家。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009759"},{"id":"00007498","register_sub_id":"101","register_pk":"108480","name":"小林家住宅門","kana":"こばやしけじゅうたくもん","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"明治","pref":"岐阜県","address":"岐阜県各務原市蘇原伊吹町3-29","lat":35.421669,"lng":136.864426,"geo_status":"db","era":"明治14","year":1881,"year_source":"db","year_min":1881,"year_max":1881,"year_label":null,"structure":"木造、瓦葺、間口3.3m","structure_material":"木造","registered":"2009.01.08(平成21.01.08)","register_no":"21 － 0170","desc":"通りに南面する一間一戸薬医門。間口３．３ｍと規模が大きく、両脇に袖塀を付け、西に潜りを開ける。切妻造桟瓦葺で、主柱上に冠木を置き、男梁を５通りに架け、軒は一軒疎垂木。装飾のない簡素な門ながら、柱や冠木、男梁は木太く、城門の雰囲気が感じられる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007498"},{"id":"00005458","register_sub_id":"101","register_pk":"106446","name":"坂井家住宅主屋","kana":"さかいけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"岐阜県","address":"岐阜県各務原市鵜沼西町1-532","lat":35.40457031,"lng":136.935959,"geo_status":"db","era":"明治27","year":1894,"year_source":"db","year_min":1894,"year_max":1894,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積189㎡","structure_material":"木造平屋建","registered":"2006.03.27(平成18.03.27)","register_no":"21 － 0086","desc":"市を東西に貫く旧中山道に北面して建つ。桁行８間半，梁間５間規模の木造つし２階建。寄棟造，平入とし，平側に下屋を張り出す。正面に切妻造の破風をつけた式台玄関を設ける格式高いつくり。旧街道沿いの民家として，多様な町並み景観の形成に寄与する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005458"},{"id":"00008117","register_sub_id":"101","register_pk":"132515","name":"酒井家住宅主屋","kana":"さかいけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"大正","pref":"岐阜県","address":"岐阜県各務原市那加西市場町2-91","lat":35.41311006,"lng":136.8247521,"geo_status":"db","era":"大正14年／昭和35年改修","year":1925,"year_source":"db","year_min":1925,"year_max":1925,"year_label":null,"structure":"木造2階建、瓦葺、建築面積171㎡","structure_material":"木造2階建","registered":"2010.04.28(平成22.04.28)","register_no":"21 － 0182","desc":"敷地中央に位置する、東西棟の切妻造桟瓦葺で、四周に下屋庇をまわす。桁行１８ｍ梁間９．６ｍの木造２階建。東寄りに土間を設け、西側に前後二列に各三室を配し、西端の南にブツマ、北にトコとトコ脇を備えた座敷を配するなど、伝統的な平面形態を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008117"},{"id":"00005459","register_sub_id":"101","register_pk":"106447","name":"坂井家住宅土蔵","kana":"さかいけじゅうたくどぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"岐阜県","address":"岐阜県各務原市鵜沼西町1-532","lat":35.4043799,"lng":136.935989,"geo_status":"db","era":"明治中期","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"土蔵造2階建、瓦葺、建築面積55㎡","structure_material":"土蔵造2階建","registered":"2006.03.27(平成18.03.27)","register_no":"21 － 0087","desc":"主屋の背後に位置し，北面して建つ。桁行５間，梁間２間規模の土蔵造２階建，切妻造，平入とし，高さの異なる棟を東西に連続させ，西の妻面には庇の持送りを塗り込めた重厚な窓を設ける。南北に細長い敷地の南東隅に位置し，屋敷構を整える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005459"},{"id":"00008118","register_sub_id":"101","register_pk":"132516","name":"酒井家住宅土蔵","kana":"さかいけじゅうたくどぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"岐阜県","address":"岐阜県各務原市那加西市場町2-91","lat":35.41324093,"lng":136.82468548,"geo_status":"db","era":"明治元年","year":1868,"year_source":"db","year_min":1868,"year_max":1868,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積34㎡","structure_material":"土蔵造2階建","registered":"2010.04.28(平成22.04.28)","register_no":"21 － 0183","desc":"敷地西北隅に南面して建つ２階建土蔵。桁行５．５ｍ梁間３．６ｍで、奥行２．７ｍと深い蔵前を付設する。切妻造桟瓦葺。内部は１、２階とも一室で、２階は土壁、１階は板張とする。外壁は高く下見板を張る白漆喰仕上げとし、敷地景観に落ち着きを与える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008118"},{"id":"00005460","register_sub_id":"101","register_pk":"106448","name":"坂井家住宅門及び塀","kana":"さかいけじゅうたくもんおよびへい","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"明治","pref":"岐阜県","address":"岐阜県各務原市鵜沼西町1-532","lat":35.40464563,"lng":136.93602155,"geo_status":"db","era":"明治中期","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"門 木造、瓦葺、間口3.6m、塀 土塀、瓦葺、延長32m","structure_material":"門 木造","registered":"2006.03.27(平成18.03.27)","register_no":"21 － 0088","desc":"旧中山道とそれに直交する路地に面して築かれる。北面に位置する門は，切妻屋根，桟瓦葺の棟門で，東脇に潜戸を付ける。塀は，路地側を鉄板で覆う。延長２２ｍの北面の土塀と，腰下見板張，延長９．５ｍの東面の土塀からなり，全体を桟瓦で葺く。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005460"},{"id":"00007497","register_sub_id":"101","register_pk":"108479","name":"清水家住宅主屋","kana":"しみずけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和前","pref":"岐阜県","address":"岐阜県各務原市蘇原伊吹町2-57","lat":35.42183448,"lng":136.86169566,"geo_status":"db","era":"昭和6","year":1931,"year_source":"db","year_min":1931,"year_max":1931,"year_label":null,"structure":"木造2階建、瓦葺、建築面積198㎡","structure_material":"木造2階建","registered":"2009.01.08(平成21.01.08)","register_no":"21 － 0169","desc":"通りの南に占める敷地の西北隅に南面して建つ。桁行１９ｍ梁間９．７ｍ規模、木造２階建の養蚕農家建築。切妻造桟瓦葺で、周囲に下屋庇をまわす。東寄りを土間とし、西に２列各３室に居室を設ける。仏間には仏壇を置き、トコと付書院を構え、良質な座敷とする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007497"},{"id":"00009456","register_sub_id":"101","register_pk":"194249","name":"清水屋原家住宅主屋","kana":"しみずやはらけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"岐阜県","address":"岐阜県中津川市馬籠4284","lat":35.5257481,"lng":137.56621133,"geo_status":"db","era":"明治後期／昭和45年改修","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"木造2階建、瓦葺、建築面積182㎡","structure_material":"木造2階建","registered":"2013.03.29(平成25.03.29)","register_no":"21 － 0205","desc":"中山道馬籠宿の南西端に建つ。間口一三・九メートル、木造二階建、切妻造桟瓦葺で正背面に庇を付ける。正面は、右手のミセ部分や二階に出格子を設け、ほかを漆喰壁や下見板張とする。内部は豪壮な梁組を現す板間を中心に座敷を配する。宿場の大型町家である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009456"},{"id":"00009457","register_sub_id":"101","register_pk":"194250","name":"清水屋原家住宅土蔵","kana":"しみずやはらけじゅうたくどぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"岐阜県","address":"岐阜県中津川市馬籠4284","lat":35.53168272,"lng":137.57163673,"geo_status":"db","era":"明治後期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"土蔵造2階建、瓦葺、建築面積30㎡","structure_material":"土蔵造2階建","registered":"2013.03.29(平成25.03.29)","register_no":"21 － 0206","desc":"主屋後方に接続し中庭に面して南北棟で建つ。土蔵造二階建、桁行五・五メートル梁間四・五メートル、切妻造桟瓦葺で、東面の戸口に下屋を設ける。外壁は漆喰塗で腰を簓子下見板張とし、戸口に土戸を両開きに吊り、上階西面に小窓を穿つ。丁寧なつくりの土蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009457"},{"id":"00002253","register_sub_id":"101","register_pk":"103243","name":"庄村家住宅西土蔵","kana":"しょうむらけじゅうたくにしどぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"岐阜県","address":"岐阜県郡上市八幡町島谷1145","lat":35.748287,"lng":136.955002,"geo_status":"db","era":"明治後期頃","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期頃","structure":"土蔵造2階建、瓦葺、建築面積27㎡","structure_material":"土蔵造2階建","registered":"2001.08.28(平成13.08.28)","register_no":"21 － 0048","desc":"米や日常道具の収蔵庫。切妻造・２階建で，東土蔵と並んで建ち，一連の屋根を架ける。吉田川の氾濫に備えるため高い玉石積基礎とし，外壁漆喰塗で腰を下見板張にする。開口部は縁取をつくり，まぐさ状の上部は虹梁型として，絵様渦文を施すなど見所がある。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002253"},{"id":"00002252","register_sub_id":"101","register_pk":"103242","name":"庄村家住宅東土蔵","kana":"しょうむらけじゅうたくひがしどぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"岐阜県","address":"岐阜県郡上市八幡町島谷1145","lat":35.748306,"lng":136.955048,"geo_status":"db","era":"明治後期頃","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期頃","structure":"土蔵造2階建、瓦葺、建築面積31㎡","structure_material":"土蔵造2階建","registered":"2001.08.28(平成13.08.28)","register_no":"21 － 0047","desc":"庄村家の敷地は南が通りに面し，北方には吉田川が流れている。敷地奥に建つ東土蔵は，刀剣や陶磁器等の収蔵庫。高さ約２メートルの玉石積基礎で，切妻造・２階建，南面１階に観音扉，北面に鉄扉付小窓を上下に設ける。外壁は丁寧なつくりの漆喰塗である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002252"},{"id":"00002254","register_sub_id":"101","register_pk":"103244","name":"庄村家住宅附属屋","kana":"しょうむらけじゅうたくふぞくや","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"岐阜県","address":"岐阜県郡上市八幡町島谷1145","lat":35.748245,"lng":136.95491,"geo_status":"db","era":"明治後期頃","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期頃","structure":"木造2階建、亜鉛メッキ鋼板葺、建築面積72㎡","structure_material":"木造2階建","registered":"2001.08.28(平成13.08.28)","register_no":"21 － 0049","desc":"土蔵の西側にあり，隠居部屋とされていた。南側は木造２階建で，各階とも板間になり，北側は下部が下見板で覆った玉石積の高い基礎で，このうえに木造の床・棚付の座敷をのせ，全体として２階建風とする。座敷廻りは数寄屋風の意匠で簡明に纏められている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002254"},{"id":"00007996","register_sub_id":"101","register_pk":"128828","name":"須賀家住宅表蔵","kana":"すがけじゅうたくおもてぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"岐阜県","address":"岐阜県下呂市萩原町中呂字沼334","lat":35.84973507,"lng":137.22585284,"geo_status":"db","era":"明治12","year":1879,"year_source":"db","year_min":1879,"year_max":1879,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積55㎡","structure_material":"土蔵造2階建","registered":"2010.01.15(平成22.01.15)","register_no":"21-0175","desc":"主屋正面の石段の東に建つ。土蔵造２階建、東西棟の置屋根形式の桟瓦葺、北に蔵前を付す。桁行７．３ｍ梁間５．５ｍ。１階に腰板を張った白漆喰仕上げ。掛子塗で平面を黒漆喰仕上げとする両開戸を吊る。赤瓦と白漆喰、黒色の木部が落ち着きのある構えをつくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007996"},{"id":"00007997","register_sub_id":"101","register_pk":"128829","name":"須賀家住宅北蔵","kana":"すがけじゅうたくきたぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"岐阜県","address":"岐阜県下呂市萩原町中呂字沼334","lat":35.85012954,"lng":137.22525785,"geo_status":"db","era":"明治25","year":1892,"year_source":"db","year_min":1892,"year_max":1892,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積21㎡","structure_material":"土蔵造2階建","registered":"2010.01.15(平成22.01.15)","register_no":"21-0176","desc":"主屋の西北に南面して建つ。桁行５．５ｍ梁間４．５ｍの土蔵造２階建、東西棟の置屋根形式の桟瓦葺、南に蔵前を付す。１階に簓子下見の腰板を張った白漆喰仕上げ。南の入口は木製の引込み戸とする。鉢巻下端の黒漆喰仕上げが外観を引き締めている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007997"},{"id":"00007995","register_sub_id":"101","register_pk":"128827","name":"須賀家住宅主屋","kana":"すがけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"岐阜県","address":"岐阜県下呂市萩原町中呂字沼334","lat":35.84989944,"lng":137.22551426,"geo_status":"db","era":"明治41","year":1908,"year_source":"db","year_min":1908,"year_max":1908,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積331㎡","structure_material":"木造平屋建","registered":"2010.01.15(平成22.01.15)","register_no":"21-0174","desc":"山裾の敷地中央に南面して建つ。つし２階建、東西棟の切妻造桟瓦葺。中央にドマやダイドコ、東にカッテバ等、西に六間取の座敷を設け、トコや棚などを備えた格調高い座敷を西北角に張り出す。正面の出桁や、架構を現す漆喰仕上げの妻壁が大規模な佇まいを誇る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007995"},{"id":"00005275","register_sub_id":"101","register_pk":"106263","name":"杉山家住宅主屋","kana":"すぎやまけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"岐阜県","address":"岐阜県羽島郡笠松町下本町63","lat":35.36549628,"lng":136.7617609,"geo_status":"db","era":"明治25","year":1892,"year_source":"db","year_min":1892,"year_max":1892,"year_label":null,"structure":"木造2階建、瓦葺、建築面積230㎡、高塀付","structure_material":"木造2階建","registered":"2006.03.02(平成18.03.02)","register_no":"21 － 0066","desc":"敷地東端に接道して建つ。桁行６間，梁間７間規模，切妻造，桟瓦葺，木造２階建の店舗兼住宅で，北側を落ち棟とし，北東隅に前庭を置く。背面南側には土間を張出す。正面外観は出桁造とし，２階外壁を漆喰で塗込める。笠松の往時の商家の姿を留め貴重。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005275"},{"id":"00006525","register_sub_id":"101","register_pk":"107508","name":"鈴木家住宅長屋門","kana":"すずきけじゅうたくながやもん","category":"住宅","subcategory":"建築物","type_guess":"門","type_guess_confidence":"high","period":"明治","pref":"岐阜県","address":"岐阜県各務原市川島松原町375","lat":35.36140248,"lng":136.82662597,"geo_status":"db","era":"明治後期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"木造平屋建、瓦葺、建築面積25㎡","structure_material":"木造平屋建","registered":"2007.07.31(平成19.07.31)","register_no":"21 － 0123","desc":"木曽川の中洲に位置し，ゴンボ積と称する玉石積で嵩上げされた屋敷地の南東部に南北棟で東面して建つ。桁行７．８ｍ，梁間３．２ｍ規模，入母屋造，桟瓦葺の木造平屋建で，両端に物置部屋を配する。東面は石垣上に建ち，前面斜路とともに屋敷地の特徴を示す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006525"},{"id":"00009018","register_sub_id":"101","register_pk":"162378","name":"都筑家住宅主屋","kana":"つづくけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"岐阜県","address":"岐阜県下呂市萩原町羽根字上段1344","lat":35.88983241,"lng":137.20042564,"geo_status":"db","era":"天保12年（1841）／安政3年（1856）増築","year":1841,"year_source":"db","year_min":1841,"year_max":1841,"year_label":null,"structure":"木造2階建、鉄板葺、建築面積384㎡","structure_material":"木造2階建","registered":"2011.10.28(平成23.10.28)","register_no":"21 － 0196","desc":"山裾に南面して建つ。切妻造鉄板葺、桁行１８ｍ梁間１７ｍの木造二階建で、西北隅に奥座敷を付設する。奥座敷は十二畳半の主室や七畳半の次の間、仏間等からなり、主室にトコや棚等を備え、次の間には大トコを構える。近世における大規模農家。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009018"},{"id":"00012539","register_sub_id":"101","register_pk":"367834","name":"都筑家住宅土蔵","kana":"つづくけじゅうたくどぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"江戸","pref":"岐阜県","address":"岐阜県下呂市萩原町羽根字上段1344","lat":35.88905,"lng":137.197189,"geo_status":"geocoded","era":"嘉永3年（1850）","year":1850,"year_source":"db","year_min":1850,"year_max":1850,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積33㎡","structure_material":"土蔵造2階建","registered":"2018.11.02(平成30.11.02)","register_no":"21 － 0264","desc":"飛騨川西岸にある屋敷地の主屋後方に建つ。土蔵造二階建、東西棟の切妻造、置屋根式で、南面に扉口と下屋を設ける。外壁は漆喰塗の腰下見板張で、西面窓を鳥居枠で飾る。大径材で二階床組をつくり、小屋組は登梁である。上層農家の伝統的な屋敷構えを伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012539"},{"id":"00006486","register_sub_id":"101","register_pk":"107469","name":"直井家住宅主屋","kana":"なおいけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"岐阜県","address":"岐阜県郡上市八幡町新町924他","lat":35.74899707,"lng":136.95757459,"geo_status":"db","era":"明治22／昭和初期増築","year":1889,"year_source":"db","year_min":1889,"year_max":1889,"year_label":null,"structure":"木造2階建、鉄板葺、建築面積252㎡","structure_material":"木造2階建","registered":"2007.10.02(平成19.10.02)","register_no":"21 － 0148","desc":"歴史的な町並みの中心となる交差点角に建つ。建築面積２５２㎡、木造２階建、鉄板葺。南側は昭和初期に増築された居室で、西隣には土蔵を接続する。２階は旧規を良くとどめ、通りに面して連続する出格子を設け、落ち着いた佇まいの街角景観を形成している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006486"},{"id":"00006487","register_sub_id":"101","register_pk":"107470","name":"直井家住宅土蔵","kana":"なおいけじゅうたくどぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"岐阜県","address":"岐阜県郡上市八幡町新町924","lat":35.74895738,"lng":136.95746996,"geo_status":"db","era":"明治初期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治初期","structure":"土蔵造2階建、鉄板葺、建築面積27㎡","structure_material":"土蔵造2階建","registered":"2007.10.02(平成19.10.02)","register_no":"21 － 0149","desc":"桁行３間、梁間２間規模で、東西棟の切妻造、鉄板葺とする。平入の土蔵造２階建。外壁は黒漆喰仕上げで、腰をモルタル塗洗出しとする。通りに面して土蔵と主屋が並ぶ当地では珍しい構えで、壁面を揃えて一体感をもたせている。黒漆喰による重厚な外観である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006487"},{"id":"00003100","register_sub_id":"101","register_pk":"104090","name":"長屋清左衛門住宅主屋","kana":"ながやせいざえもんじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"岐阜県","address":"岐阜県関市板取1556-1","lat":35.6998299,"lng":136.80521227,"geo_status":"db","era":"江戸中期","year":1735,"year_source":"estimated","year_min":1661,"year_max":1751,"year_label":"江戸中期","structure":"木造平屋建、鉄板葺、建築面積280㎡","structure_material":"木造平屋建","registered":"2003.01.31(平成15.01.31)","register_no":"21 － 0050","desc":"美濃地方北部の山間部にある庄屋の住宅。主屋は１２間に６間半の大規模なもので，南を正面とし，西を上手とする。現在鉄板葺の緩勾配，切妻造の大屋根は以前は杉皮葺であった。後世の改造は多いが１７世紀に遡る遺構と見られる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003100"},{"id":"00003101","register_sub_id":"101","register_pk":"104091","name":"長屋清左衛門住宅長屋門","kana":"ながやせいざえもんじゅうたくながやもん","category":"住宅","subcategory":"建築物","type_guess":"門","type_guess_confidence":"high","period":"江戸","pref":"岐阜県","address":"岐阜県関市板取1556-1","lat":35.699703,"lng":136.80544286,"geo_status":"db","era":"江戸後期","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造、鉄板葺、建築面積52㎡","structure_material":"木造","registered":"2003.01.31(平成15.01.31)","register_no":"21 － 0051","desc":"敷地東面の主屋南東側に東を正面として建つ切妻造の長屋門。屋根は主屋同様鉄板葺であるが以前は杉皮葺であったと見られる。前後の軒をせがいとし，深い軒の出を造る。近世の庄屋住宅の構成要素として欠かせない物件。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003101"},{"id":"00005976","register_sub_id":"101","register_pk":"106961","name":"丹羽家住宅主屋","kana":"にわけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和前","pref":"岐阜県","address":"岐阜県各務原市鵜沼西町1-923","lat":35.404968,"lng":136.933777,"geo_status":"db","era":"昭和5","year":1930,"year_source":"db","year_min":1930,"year_max":1930,"year_label":null,"structure":"木造2階建、瓦葺、建築面積174㎡","structure_material":"木造2階建","registered":"2006.11.29(平成18.11.29)","register_no":"21 － 0108","desc":"旧中山道鵜沼宿の旧街道の北側角地に建つ。木造２階建，切妻造平入の町家である。桁行８間，梁間４間で表裏に下屋が付く。１階は東が土間で背面に水屋を突出する。西の居室は８畳規模の整形四間取で下屋を縁としている。旧街道の様子が窺える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005976"},{"id":"00011312","register_sub_id":"101","register_pk":"209149","name":"花田今井家住宅蔵","kana":"はなたいまいけじゅうたくくら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"岐阜県","address":"岐阜県下呂市御厩野字花田垣内149-1","lat":35.760927,"lng":137.317227,"geo_status":"db","era":"明治8頃","year":1875,"year_source":"db","year_min":1875,"year_max":1875,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積38㎡","structure_material":"土蔵造2階建","registered":"2016.11.29(平成28.11.29)","register_no":"21－0246","desc":"主屋背面側に建つ土蔵。切妻造妻入で、桟瓦葺の置屋根形式。外壁は漆喰塗で腰部を高く竪板張で覆う。内部は一・二階とも板敷とし、隅を区画して押入状に設える。簡素ではあるが、正面扉回りなどの意匠に意を凝らした外観で、敷地景観を形成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011312"},{"id":"00011311","register_sub_id":"101","register_pk":"209148","name":"花田今井家住宅主屋","kana":"はなたいまいけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"岐阜県","address":"岐阜県下呂市御厩野字花田垣内149-1","lat":35.760802,"lng":137.317129,"geo_status":"db","era":"文政12／昭和24増築、昭和44改修","year":1829,"year_source":"db","year_min":1829,"year_max":1829,"year_label":null,"structure":"木造2階建、瓦葺、建築面積310㎡","structure_material":"木造2階建","registered":"2016.11.29(平成28.11.29)","register_no":"21－0245","desc":"木造二階建、切妻造桟瓦葺で、桁行一六メートルの大規模民家。正面右寄りを土間、左側を床上部としていたものの土間側を洋風の医院として増改築したもの。二階は増築部以外を広く一室とし、蚕室に用いたと考えられる。近世から近代まで各時代の様相を併せ持つ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011311"},{"id":"00011313","register_sub_id":"101","register_pk":"209150","name":"花田今井家住宅水車小屋・味噌蔵及び納屋","kana":"はなたいまいけじゅうたくすいしゃごや・みそぐらおよびなや","category":"住宅","subcategory":"建築物","type_guess":"茶室・離れ","type_guess_confidence":"high","period":"昭和前","pref":"岐阜県","address":"岐阜県下呂市御厩野字花田垣内149-1","lat":35.760977,"lng":137.317154,"geo_status":"db","era":"昭和初期／昭和55改修","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和初期","structure":"木造2階建、瓦葺、建築面積53㎡","structure_material":"木造2階建","registered":"2016.11.29(平成28.11.29)","register_no":"21－0247","desc":"主屋背面、蔵の西隣に建つ。水車小屋、味噌蔵、納屋を複合させた建物で、西面北寄りを水車小屋、その南に味噌蔵を建て、これらを覆う形で納屋を建てている。水車小屋が残る希少な例で、大規模農家の附属屋のさまざまな機能を知ることのできる建物である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011313"},{"id":"00011314","register_sub_id":"101","register_pk":"209151","name":"花田今井家住宅門及び塀","kana":"はなたいまいけじゅうたくもんおよびへい","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"昭和中","pref":"岐阜県","address":"岐阜県下呂市御厩野字花田垣内149-1","lat":35.76083359,"lng":137.31691993,"geo_status":"db","era":"昭和31頃","year":1956,"year_source":"db","year_min":1956,"year_max":1956,"year_label":null,"structure":"門 木造、瓦葺、間口1.7m 塀 木造、瓦葺、総延長38m","structure_material":"門 木造","registered":"2016.11.29(平成28.11.29)","register_no":"21－0248","desc":"主屋西南隅から西方に伸びる塀。主屋脇には一間幅の簡易な腕木門を設ける。塀は基礎石に土台を載せて一間毎に柱を建て、柱間を下部洗い出し、上部漆喰塗とする。屋根は門を含めてセメント桟瓦で葺く。長大な漆喰塗の外観で、地域の景観に寄与している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011314"},{"id":"00012536","register_sub_id":"101","register_pk":"367831","name":"藤田家住宅主屋","kana":"ふじたけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"岐阜県","address":"岐阜県岐阜市東材木町29-2","lat":35.434525,"lng":136.769119,"geo_status":"geocoded","era":"明治45年頃／大正4年移築","year":1912,"year_source":"db","year_min":1912,"year_max":1912,"year_label":null,"structure":"木造2階一部平屋建、瓦葺、建築面積144㎡","structure_material":"木造2階一部平屋建","registered":"2018.11.02(平成30.11.02)","register_no":"21 － 0261","desc":"岐阜旧城下にある味噌醸造を営んだ商家。主屋は東面して建ち、総二階建切妻造の表屋背面に平屋建切妻造の角屋を付す。表屋は南に土間を通す1列3室型、角屋は台所兼醸造場で梁組を現す。平格子と出格子を組み合せた表構えなど城下の伝統町家の構成を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012536"},{"id":"00012537","register_sub_id":"101","register_pk":null,"name":"藤田家住宅土蔵","kana":"ふじたけじゅうたくどぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"昭和前","pref":"岐阜県","address":"岐阜県岐阜市東材木町29-2","lat":35.434525,"lng":136.769119,"geo_status":"geocoded","era":"昭和4年／平成15年移築","year":1929,"year_source":"db","year_min":1929,"year_max":1929,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積31㎡","structure_material":"土蔵造2階建","registered":"2018.11.02(平成30.11.02)","register_no":"21 － 0262","desc":"主屋後方に建つ。土蔵造二階建、南北棟の切妻造桟瓦葺妻入で、南面に戸口を設けて下屋を付す。市外からの移築建物で内部が改変されているが、欅の良材を用いた柱など主要な構造部をよく残し、半間毎に立てた柱や登梁の小屋組など伝統的な土蔵の形式を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012537"},{"id":"00011959","register_sub_id":"101","register_pk":"211103","name":"抱石庵（久松真一記念館）","kana":"ほうせきあん（ひさまつしんいちきねんかん）","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"岐阜県","address":"岐阜県岐阜市大字長良福光字生田227","lat":35.45879,"lng":136.776098,"geo_status":"db","era":"大正2年","year":1913,"year_source":"db","year_min":1913,"year_max":1913,"year_label":null,"structure":"木造2階建、瓦葺、建築面積100㎡","structure_material":"木造2階建","registered":"2017.10.27(平成29.10.27)","register_no":"21-255","desc":"木造二階建で、一階は玄関を入り、畳縁を介して座敷、次の間を配し、その西に仏間、茶室を設ける。二階は南・西に畳廊下を取り、座敷一二畳を配す。座敷飾や天井に技巧を凝らし、二階をガラス戸で明るい空間とするなど、近代和風住宅の特色をよく示す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011959"},{"id":"00005603","register_sub_id":"101","register_pk":"106591","name":"保々家住宅主屋","kana":"ほぼけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"岐阜県","address":"岐阜県瑞浪市大湫町402-1","lat":35.43333839,"lng":137.29397125,"geo_status":"db","era":"江戸中期／江戸後期改造","year":1735,"year_source":"estimated","year_min":1661,"year_max":1751,"year_label":"江戸中期","structure":"木造平屋建、瓦葺、建築面積161㎡","structure_material":"木造平屋建","registered":"2006.08.03(平成18.08.03)","register_no":"21 － 0090","desc":"中山道大湫宿の脇本陣で，街道の西側奥の高台に建つ。南東に面する切妻造，桟瓦葺，平屋建，平入で，正面の庇上の小壁には木瓜形の窓や桔梗紋の漆喰飾を設ける。南側にあった玄関や座敷が失われているが，往時の宿場の中心的な建築として，景観を形成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005603"},{"id":"00009460","register_sub_id":"101","register_pk":"194253","name":"松屋山田家住宅","kana":"まつややまだけじゅうたく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"low","period":"明治","pref":"岐阜県","address":"岐阜県可児郡御嵩町伏見字西町924-1","lat":35.43887687,"lng":137.08461456,"geo_status":"db","era":"明治30年／昭和8年増築","year":1897,"year_source":"db","year_min":1897,"year_max":1897,"year_label":null,"structure":"木造2階建、瓦葺、建築面積196㎡","structure_material":"木造2階建","registered":"2013.03.29(平成25.03.29)","register_no":"21 － 0209","desc":"中山道伏見宿で、通りに北面して建つ。間口一五・一メートルの主体部は、木造二階建、切妻造桟瓦葺で正背面に庇を付ける。東側にモルタル塗で洋風意匠の旧郵便局を付属する。正面は下階全体に格子を、上階にガラス窓をたてる。宿場の名残を伝える近代の町家。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009460"},{"id":"00005604","register_sub_id":"101","register_pk":"106592","name":"三浦家住宅主屋","kana":"みうらけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"岐阜県","address":"岐阜県瑞浪市大湫町442-1","lat":35.43384059,"lng":137.29521502,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造2階建、瓦葺、建築面積141㎡","structure_material":"木造2階建","registered":"2006.08.03(平成18.08.03)","register_no":"21 － 0091","desc":"中山道大湫宿にある旅籠を兼ねた住宅で，街道に北面して建つ。切妻造，桟瓦葺，２階建の平入で，正面と東側に下屋を設ける。１階は東に３室，西は土間や台所等とし，表側２階を部屋とする。正面開口部に格子を構えた外観は，宿場の景観をよく伝えている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005604"},{"id":"00006656","register_sub_id":"101","register_pk":"107639","name":"水野家住宅主屋","kana":"みずのけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和前","pref":"岐阜県","address":"岐阜県各務原市川島松原町字山神西382","lat":35.36187166,"lng":136.82695072,"geo_status":"db","era":"昭和3","year":1928,"year_source":"db","year_min":1928,"year_max":1928,"year_label":null,"structure":"木造2階建、瓦葺、建築面積179㎡","structure_material":"木造2階建","registered":"2007.12.05(平成19.12.05)","register_no":"21 － 0153","desc":"敷地西辺寄りに南面して建つ。桁行８間梁間４間を総２階とし、１階周囲に庇を廻す。切妻造桟瓦葺。東寄りに土間を設け、西側に８畳間４室やブツマなどを設ける。２階は土間上を板敷とし、西側に５室を設ける。この地方の近代養蚕農家の特色をよく残す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006656"},{"id":"00006488","register_sub_id":"101","register_pk":"107471","name":"水野家住宅主屋","kana":"みずのけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"大正","pref":"岐阜県","address":"岐阜県郡上市八幡町新町925","lat":35.748852,"lng":136.957428,"geo_status":"db","era":"大正期／昭和中期増築","year":1919,"year_source":"estimated","year_min":1912,"year_max":1926,"year_label":"大正期","structure":"木造2階建、鉄板葺、建築面積165㎡","structure_material":"木造2階建","registered":"2007.10.02(平成19.10.02)","register_no":"21 － 0150","desc":"縦長敷地の通り沿いに建つ。建築面積１６５㎡、木造２階建、鉄板葺。正面は２階に連続する出格子を設け、軒は出桁造とし、屋根には当地では珍しい卯建をあげる。内外ともに上質なつくりで、歴史的町並みの形成に寄与している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006488"},{"id":"00006489","register_sub_id":"101","register_pk":"107472","name":"水野家住宅土蔵","kana":"みずのけじゅうたくどぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"岐阜県","address":"岐阜県郡上市八幡町新町925","lat":35.748932,"lng":136.957397,"geo_status":"db","era":"明治期","year":1890,"year_source":"estimated","year_min":1868,"year_max":1912,"year_label":"明治期","structure":"土蔵造2階建、鉄板葺、建築面積18㎡","structure_material":"土蔵造2階建","registered":"2007.10.02(平成19.10.02)","register_no":"21 － 0151","desc":"主屋の東隣に建ち、桁行３間、梁間１間半、土蔵造２階建。屋根は切妻造鉄板葺で、正面は主屋と軒を揃えて一体的にし、東端に卯建をあげる。白漆喰仕上げで、窓上枠に唐草文をあしらい、庇に起りをつけ、こけら葺とするなど、瀟洒な外観である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006489"},{"id":"00005605","register_sub_id":"101","register_pk":"106593","name":"森川訓行家住宅主屋","kana":"もりかわのりゆきけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"岐阜県","address":"岐阜県瑞浪市大湫町445-2","lat":35.43376405,"lng":137.29511581,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造2階建、瓦葺、建築面積185㎡","structure_material":"木造2階建","registered":"2006.08.03(平成18.08.03)","register_no":"21 － 0092","desc":"中山道大湫宿の旅籠や問屋を兼ねた住宅。街道に北面して建ち，切妻造，桟瓦葺，２階建の平入で，正面と西側に下屋を廻す。１階は西を３室２列の居室，東を土間とし，２階は表側に部屋を設ける。正面の格子，両妻の漆喰塗の袖壁など，宿場の景観をよく残す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005605"},{"id":"00005606","register_sub_id":"101","register_pk":"106594","name":"森川善章家住宅主屋","kana":"もりかわよしあきけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"岐阜県","address":"岐阜県瑞浪市大湫町463-1","lat":35.43285586,"lng":137.29419668,"geo_status":"db","era":"明治26","year":1893,"year_source":"db","year_min":1893,"year_max":1893,"year_label":null,"structure":"木造2階建、瓦葺、建築面積145㎡","structure_material":"木造2階建","registered":"2006.08.03(平成18.08.03)","register_no":"21 － 0093","desc":"旧中山道大湫宿の旅宿や問屋を兼ねた住宅。街道に北面して建ち，木造２階建，切妻造，桟瓦葺，平入で，正面と両側に下屋を廻す。１階は３室２列の居室と土間，２階は６室に間仕切る。たちの高いつくりは近代の傾向を示すが，旧街道の町並み景観をよく残す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005606"},{"id":"00006190","register_sub_id":"101","register_pk":"107174","name":"安田家住宅主屋","kana":"やすだけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和前","pref":"岐阜県","address":"岐阜県各務原市鵜沼西町1-528","lat":35.40464159,"lng":136.9353521,"geo_status":"db","era":"昭和5頃","year":1930,"year_source":"db","year_min":1930,"year_max":1930,"year_label":null,"structure":"木造2階建、瓦葺、建築面積128㎡","structure_material":"木造2階建","registered":"2007.05.15(平成19.05.15)","register_no":"21 － 0110","desc":"旧中山道に北面して建つ木造２階建。８畳４室の整形四間取とし，東側に土間を設ける。切妻造，桟瓦葺，平入で，正面に瓦葺の庇を付ける。正面外壁は鼠漆喰塗とし，開口部に格子を付ける。坂井家住宅（登録）等の町家と連続して並び，宿場の景観を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006190"},{"id":"00000242","register_sub_id":"101","register_pk":"101232","name":"矢橋家住宅隠居（竹雪廬）","kana":"やばしけじゅうたくいんきょ（ちくせつろ）","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"江戸","pref":"岐阜県","address":"岐阜県大垣市赤坂町226","lat":35.39051108,"lng":136.58157038,"geo_status":"db","era":"文化2","year":1805,"year_source":"db","year_min":1805,"year_max":1805,"year_label":null,"structure":"木造平屋建，瓦葺，建築面積78㎡","structure_material":"木造平屋建","registered":"1997.07.15(平成9.07.15)","register_no":"21 － 0003","desc":"中山道に北面する敷地の西端にあり、道路に面して建つ。平屋建てだが、屋根は２重にする。道路側に千本格子を入れ外観を町屋風にし、内部は細かく部屋を仕切る。屋敷内最古の建物で、各部に用いられている材料や仕上げ等は良質である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000242"},{"id":"00000244","register_sub_id":"101","register_pk":"101234","name":"矢橋家住宅表門","kana":"やばしけじゅうたくおもてもん","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"江戸","pref":"岐阜県","address":"岐阜県大垣市赤坂町226","lat":35.39054006,"lng":136.58159661,"geo_status":"db","era":"嘉永年間","year":1851,"year_source":"estimated","year_min":1848,"year_max":1854,"year_label":"嘉永年間","structure":"木造平屋建板塀付，瓦葺","structure_material":"木造平屋建板塀付","registered":"1997.07.15(平成9.07.15)","register_no":"21 － 0005","desc":"主屋と隠居の間にある中山道に面して設けられた門で、左右には塀が附属する。書院と同時期に建設されたと推定される。黒漆喰仕上げで腰に板を張る塀の意匠は、主屋と意匠の調和が図られており、大規模な屋敷構えの特徴をよく表す要素となっている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000244"},{"id":"00000241","register_sub_id":"101","register_pk":"101231","name":"矢橋家住宅主屋","kana":"やばしけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"岐阜県","address":"岐阜県大垣市赤坂町226","lat":35.39045249,"lng":136.58164977,"geo_status":"db","era":"天保4","year":1833,"year_source":"db","year_min":1833,"year_max":1833,"year_label":null,"structure":"木造2階建，瓦葺，建築面積284㎡","structure_material":"木造2階建","registered":"1997.07.15(平成9.07.15)","register_no":"21 － 0002","desc":"中山道に北面する平入の大型町屋。２階の軒裏やうだつを黒漆喰塗りとし１・２階ともに千本格子をはめる等、正面外観は瀟洒な意匠になる。大規模ながら２階をつしとする点等に、江戸時代末期の地方都市における大型町屋の特徴がよく表れている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000241"},{"id":"00000243","register_sub_id":"101","register_pk":"101233","name":"矢橋家住宅書院（紅於亭）","kana":"やばしけじゅうたくしょいん（こうおてい）","category":"住宅","subcategory":"建築物","type_guess":"茶室・離れ","type_guess_confidence":"high","period":"江戸","pref":"岐阜県","address":"岐阜県大垣市赤坂町226","lat":35.39040341,"lng":136.58158004,"geo_status":"db","era":"嘉永年間","year":1851,"year_source":"estimated","year_min":1848,"year_max":1854,"year_label":"嘉永年間","structure":"木造平屋建，瓦葺，建築面積84㎡","structure_material":"木造平屋建","registered":"1997.07.15(平成9.07.15)","register_no":"21 － 0004","desc":"主屋の西に接続する二間続きの座敷。北東には表門に通じる式台玄関を設ける。平屋建てだが屋根は二重にする。玄関式台の黒漆喰に四半敷きの目地を付けた土間床、網代編みにした腰壁等に数寄屋造に通じる高い技能が用いられている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000243"},{"id":"00000245","register_sub_id":"101","register_pk":"101235","name":"矢橋家住宅茶室","kana":"やばしけじゅうたくちゃしつ","category":"住宅","subcategory":"建築物","type_guess":"茶室・離れ","type_guess_confidence":"high","period":"明治","pref":"岐阜県","address":"岐阜県大垣市赤坂町226","lat":35.39030818,"lng":136.58151517,"geo_status":"db","era":"明治初頃","year":1868,"year_source":"db","year_min":1868,"year_max":1868,"year_label":null,"structure":"木造平屋建，瓦葺，建築面積32㎡","structure_material":"木造平屋建","registered":"1997.07.15(平成9.07.15)","register_no":"21 － 0006","desc":"書院の南東に接続する。内部は茶室と水屋からなる。節のある細い柱を用い深い軒の出をつくる等、軽快で品の良い意匠でまとまられている。江戸時代以来続く大規模な屋敷の中には、瀟洒な茶室がしばしばつくられているが、この建物はその好例である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000245"},{"id":"00000247","register_sub_id":"101","register_pk":"101237","name":"矢橋家住宅中蔵","kana":"やばしけじゅうたくなかぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"江戸","pref":"岐阜県","address":"岐阜県大垣市赤坂町226","lat":35.3901453,"lng":136.58149171,"geo_status":"db","era":"天保年間","year":1837,"year_source":"estimated","year_min":1830,"year_max":1844,"year_label":"天保年間","structure":"木造2階建，瓦葺，建築面積52㎡","structure_material":"木造2階建","registered":"1997.07.15(平成9.07.15)","register_no":"21 － 0008","desc":"他の土蔵と基本的に同様の意匠であるが、北側の主屋に面した側の妻面に出入口を設けている点が異なる。竣工は主屋・東蔵と同じく天保年間と思われる。２階の一部には扉が設けられ、重厚な外観の中でアクセントとなっている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000247"},{"id":"00000248","register_sub_id":"101","register_pk":"101238","name":"矢橋家住宅西蔵","kana":"やばしけじゅうたくにしぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"岐阜県","address":"岐阜県大垣市赤坂町226","lat":35.3901246,"lng":136.58139095,"geo_status":"db","era":"明治初頃","year":1868,"year_source":"db","year_min":1868,"year_max":1868,"year_label":null,"structure":"木造2階建，瓦葺，建築面積61㎡","structure_material":"木造2階建","registered":"1997.07.15(平成9.07.15)","register_no":"21 － 0009","desc":"３棟の土蔵のうち、もっとも大規模なものである。東面には吹き放ちの庇を設け蔵前とする。漆喰塗大壁造の外壁をさらに簓子下見板張りとする点は他の蔵と同様であるが、出入口が２カ所設けられている事と、２階に漆喰塗扉が多く設けられている点が異なる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000248"},{"id":"00000246","register_sub_id":"101","register_pk":"101236","name":"矢橋家住宅東蔵","kana":"やばしけじゅうたくひがしぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"江戸","pref":"岐阜県","address":"岐阜県大垣市赤坂町226","lat":35.39009147,"lng":136.58165596,"geo_status":"db","era":"天保年間","year":1837,"year_source":"estimated","year_min":1830,"year_max":1844,"year_label":"天保年間","structure":"木造2階建，瓦葺，建築面積29㎡","structure_material":"木造2階建","registered":"1997.07.15(平成9.07.15)","register_no":"21 － 0007","desc":"３棟の土蔵の内最も小規模なもので、主屋と同時期の建築と思われる。西側に出入口を設け、吹き放ちの庇を設けて蔵前とする。簓子下見板張りとし、けらばも板張りとなる外観が特徴で、屋敷構えの特徴をよく表す要素となっている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000246"},{"id":"00011699","register_sub_id":"101","register_pk":"210715","name":"和田家住宅主屋","kana":"わだけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和前","pref":"岐阜県","address":"岐阜県羽島郡笠松町字八幡町96","lat":35.368917,"lng":136.762629,"geo_status":"db","era":"昭和前期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和前期","structure":"木造2階建、瓦葺、建築面積194㎡","structure_material":"木造2階建","registered":"2017.06.28(平成29.06.28)","register_no":"21-0252","desc":"笠松町中心地に建つ。東面に玄関と脇玄関を設け、中廊下を挟み南に居室、北に接客空間として三室を並べる。仏間には吹寄せ桟の格天井を吊り、西端の座敷も上質な床構えを持つ。二階の洋間は窓にステンドグラスを用い、漆喰天井も丁寧な仕上げの住宅建築である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011699"},{"id":"00011700","register_sub_id":"101","register_pk":"210716","name":"和田家住宅土蔵","kana":"わだけじゅうたくどぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"昭和前","pref":"岐阜県","address":"岐阜県羽島郡笠松町字八幡町96","lat":35.368964,"lng":136.762446,"geo_status":"db","era":"昭和前期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和前期","structure":"土蔵造2階建、瓦葺、建築面積41㎡","structure_material":"土蔵造2階建","registered":"2017.06.28(平成29.06.28)","register_no":"21-0253","desc":"敷地西南隅に東面し、主屋から延びる土間で接続する。丸石を亀甲積にし、一段高い位置に建ち、桁行四間、梁間三間、妻入で、内部は板張で一、二階とも一室である。一階南面、二階東面の窓は重厚な土扉で、外壁は腰板張とし、街路景観を形成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011700"},{"id":"00011701","register_sub_id":"101","register_pk":"210717","name":"和田家住宅門及び塀","kana":"わだけじゅうたくもんおよびへい","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"昭和前","pref":"岐阜県","address":"岐阜県羽島郡笠松町字八幡町96他","lat":35.368878,"lng":136.762762,"geo_status":"db","era":"昭和前期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和前期","structure":"門 木造、瓦葺、間口1.7m、左右袖塀付 塀 木造、瓦葺、総延長18m","structure_material":"門 木造","registered":"2017.06.28(平成29.06.28)","register_no":"21-0254","desc":"敷地の東と南を画する。東面にある門は、間口一・七メートル、両脇に袖塀付で、両端と南面へ塀が続く。塀は、内側の庭に面しては竹で窓を意匠し、腰部は杉皮張で数寄屋風意匠をみせ、外側では黒漆喰塗とし、腰板張を連続させ、内外の景観を良好に形成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011701"},{"id":"00004970","register_sub_id":"101","register_pk":"105960","name":"渡邉家住宅上手蔵","kana":"わたなべけじゅうたくかみてぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"岐阜県","address":"岐阜県飛騨市古川町壱之町7-3","lat":36.2354978,"lng":137.18646848,"geo_status":"db","era":"明治5","year":1872,"year_source":"db","year_min":1872,"year_max":1872,"year_label":null,"structure":"土蔵造2階建、鉄板葺、建築面積53㎡","structure_material":"土蔵造2階建","registered":"2005.11.10(平成17.11.10)","register_no":"21 － 0063","desc":"敷地後方の瀬戸川沿いにある。土蔵造２階建，方４間の正方形平面で，１階は西半を土間，東半に床を張る。西面１階には観音開扉，東面に窓２段を設け，屋根は段違いの鉄板葺置屋根式，外壁は漆喰塗である。古川を特長づける土蔵群の町並景観の構成要素である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004970"},{"id":"00004968","register_sub_id":"101","register_pk":"105958","name":"渡邉家住宅主屋","kana":"わたなべけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"岐阜県","address":"岐阜県飛騨市古川町壱之町7-3","lat":36.23540507,"lng":137.18633942,"geo_status":"db","era":"江戸末期／明治37移築","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造2階建、鉄板葺、建築面積239㎡","structure_material":"木造2階建","registered":"2005.11.10(平成17.11.10)","register_no":"21 － 0061","desc":"２階建の切妻造，鉄板葺，平入の伝統的な町家で，町並景観のランドマーク的存在。１階は梁組をみせる土間と繊細な数寄屋風の居室からなり，２階には座敷や茶室がある。街路沿いの正面は深い軒をつくり，階境には腕木式の板庇をつけ，格子は多彩で変化に富む。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004968"},{"id":"00004969","register_sub_id":"101","register_pk":"105959","name":"渡邉家住宅漬物蔵","kana":"わたなべけじゅうたくつけものぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"江戸","pref":"岐阜県","address":"岐阜県飛騨市古川町壱之町7-3","lat":36.23540652,"lng":137.18658169,"geo_status":"db","era":"元治元","year":1864,"year_source":"db","year_min":1864,"year_max":1864,"year_label":null,"structure":"土蔵造2階建、鉄板葺、建築面積39㎡","structure_material":"土蔵造2階建","registered":"2005.11.10(平成17.11.10)","register_no":"21 － 0062","desc":"敷地後方南端の瀬戸川沿いにある。土蔵造２階建で，西面１階に観音開扉を構え，東面に窓を設ける。小屋は牛梁に登梁を架け，屋根は置屋根式の鉄板葺である。外壁は漆喰塗，東面の腰は押縁下見板張で覆う。古川を特長づける土蔵群の町並景観の構成要素である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004969"},{"id":"00003855","register_sub_id":"101","register_pk":"104845","name":"渡邉家住宅土蔵別館","kana":"わたなべけじゅうたくどぞうべっかん","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"昭和前","pref":"岐阜県","address":"岐阜県飛騨市古川町壱之町7-3","lat":36.23520657,"lng":137.18622088,"geo_status":"db","era":"昭和9","year":1934,"year_source":"db","year_min":1934,"year_max":1934,"year_label":null,"structure":"土蔵造2階建、鉄板葺、建築面積40㎡","structure_material":"土蔵造2階建","registered":"2004.02.17(平成16.02.17)","register_no":"21 － 0052","desc":"土蔵造２階建，入母屋造，鉄板葺の離座敷。瀬戸川に面し，土蔵造の酒蔵と漬物蔵に挟まれる。川側外壁は目地切のモルタル洗出し，１階１０畳座敷の広縁，２階洋室の洋風縦長窓を開き，胴蛇腹風の小庇，軒蛇腹風の鉢巻で洋風を表現する。棟梁は古川の中村房吉。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003855"},{"id":"00004971","register_sub_id":"101","register_pk":"105961","name":"渡邉家住宅中蔵","kana":"わたなべけじゅうたくなかぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"江戸","pref":"岐阜県","address":"岐阜県飛騨市古川町壱之町7-3","lat":36.23556183,"lng":137.18640576,"geo_status":"db","era":"享和4","year":1804,"year_source":"db","year_min":1804,"year_max":1804,"year_label":null,"structure":"土蔵造2階建、鉄板葺、建築面積53㎡","structure_material":"土蔵造2階建","registered":"2005.11.10(平成17.11.10)","register_no":"21 － 0064","desc":"敷地後方の瀬戸川沿いにあり，古川を特長づける土蔵群の町並景観の構成要素である。土蔵造２階建，ほぼ方４間の平面で，西面１階には重厚な観音開扉を構え，１階の南西隅は踏込みの土間とする。小屋は登梁式で，屋根は置屋根式の鉄板葺，外壁は漆喰塗である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004971"},{"id":"00000774","register_sub_id":"101","register_pk":"101764","name":"伊藤家住宅主屋","kana":"いとうけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和前","pref":"静岡県","address":"静岡県静岡市清水区上清水町273-4","lat":35.01029051,"lng":138.48097343,"geo_status":"db","era":"昭和14","year":1939,"year_source":"db","year_min":1939,"year_max":1939,"year_label":null,"structure":"木造平屋建，瓦葺，建築面積106㎡","structure_material":"木造平屋建","registered":"1998.09.02(平成10.09.02)","register_no":"22 － 0015","desc":"木造平屋建で，屋根は東側が切妻，西側を寄棟とする変則的な構成になり，正面に入母屋屋根の玄関が付設する。内部は，建具や欄間は神代杉を用いた丁寧な造りとなり，座敷はじめ各室とも全体に保存がよい。清水市郊外の戦前の和風住宅の一つとして知られる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000774"},{"id":"00005839","register_sub_id":"101","register_pk":"106825","name":"梅御殿","kana":"うめごてん","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"静岡県","address":"静岡県三島市一番町15-6","lat":35.123642,"lng":138.91214,"geo_status":"db","era":"明治中期","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"木造2階建、銅板葺、建築面積150㎡","structure_material":"木造2階建","registered":"2006.10.18(平成18.10.18)","register_no":"22 － 0114","desc":"旧小松宮三島別邸の一部。池に臨む主座敷の床柱に梅が用いられている。敷地の高低差を利用したスキップフロアー状の建物で，西方の下階に玄関を設け，東方の上階に６畳と９畳３室を並べ，東南矩折れに１０畳座敷を配する。数寄屋意匠による宮家住宅の一事例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005839"},{"id":"00006848","register_sub_id":"101","register_pk":"107830","name":"大箸家住宅井戸小屋","kana":"おおはしけじゅうたくいどごや","category":"住宅","subcategory":"その他工作物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"静岡県","address":"静岡県磐田市壱貫地字道上429-1","lat":34.82597357,"lng":137.8347822,"geo_status":"db","era":"昭和前期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和前期","structure":"木造、鉄板葺、面積4.6㎡","structure_material":"木造","registered":"2008.03.07(平成20.03.07)","register_no":"22 － 0129","desc":"敷地南門から主屋に延びる通路の東側に建つ。間口２．３ｍ、奥行２．０ｍ、切妻造鉄板葺。コンクリート製の礎石に、方柱の４本柱を四方転びに建て、内法貫と桁で頂部を固める。コンクリート製の井戸枠や釣瓶をかける滑車を残し、生活感のある佇まいをみせる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006848"},{"id":"00006850","register_sub_id":"101","register_pk":"107832","name":"大箸家住宅内塀","kana":"おおはしけじゅうたくうちべい","category":"住宅","subcategory":"その他工作物","type_guess":"塀","type_guess_confidence":"high","period":"昭和前","pref":"静岡県","address":"静岡県磐田市壱貫地字道上429-1","lat":34.82588224,"lng":137.83470643,"geo_status":"db","era":"昭和前期／昭和30頃改修","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和前期","structure":"木造、銅板葺、延長28m","structure_material":"木造","registered":"2008.03.07(平成20.03.07)","register_no":"22 － 0131","desc":"敷地南面の門の西脇から主屋の座敷部前面に向けて矩折れに延び、内庭入口に庭門を開く。高さ１．６ｍ、延長２８ｍ、玉石積の基礎上に土台を伏せ、軸部は大和塀形式とし、頂部には垂木を配して銅板屋根を葺く。外庭と内庭を区画し、上質な屋敷内景観をつくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006850"},{"id":"00006845","register_sub_id":"101","register_pk":"107827","name":"大箸家住宅北土蔵","kana":"おおはしけじゅうたくきたどぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"静岡県","address":"静岡県磐田市壱貫地字道上429-1","lat":34.82592984,"lng":137.83490443,"geo_status":"db","era":"明治前期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"土蔵造2階建、瓦葺、建築面積47㎡","structure_material":"土蔵造2階建","registered":"2008.03.07(平成20.03.07)","register_no":"22 － 0126","desc":"主屋の南東寄り、南土蔵と納屋の間に西面して建つ。桁行７．３ｍ梁間４．５ｍ、土蔵造２階建、切妻造桟瓦葺で、西側に１間通りの蔵前を設ける。水害対策のため伊豆石を積んだ基壇に建ち、腰を海鼠壁とする。古文書などを収蔵した蔵で、屋敷構えに趣を添える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006845"},{"id":"00006844","register_sub_id":"101","register_pk":"107826","name":"大箸家住宅主屋","kana":"おおはしけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"静岡県","address":"静岡県磐田市壱貫地字道上429-1","lat":34.82611747,"lng":137.83465384,"geo_status":"db","era":"江戸末期／明治前期改修","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造2階建、瓦葺、建築面積269㎡","structure_material":"木造2階建","registered":"2008.03.07(平成20.03.07)","register_no":"22 － 0125","desc":"天竜川東側の敷地中央に南面して建つ。建築面積２６９㎡、木造２階建、寄棟造桟瓦葺。正面中央に式台玄関を設け、内部の東側はもと土間で、西側の床上部は鍵座敷とし、奥座敷にトコ、天袋、平書院を設ける。もと酒造業を営んでいた庄屋の風格を示す大型の住宅。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006844"},{"id":"00006849","register_sub_id":"101","register_pk":"107831","name":"大箸家住宅外塀","kana":"おおはしけじゅうたくそとべい","category":"住宅","subcategory":"その他工作物","type_guess":"塀","type_guess_confidence":"high","period":"昭和前","pref":"静岡県","address":"静岡県磐田市壱貫地字道上429-1","lat":34.82603629,"lng":137.83449878,"geo_status":"db","era":"昭和前期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和前期","structure":"木造、鉄板葺、延長49m","structure_material":"木造","registered":"2008.03.07(平成20.03.07)","register_no":"22 － 0130","desc":"敷地南東隅から西辺に沿って矩折れに延びる。高さ１．８ｍ、延長４９ｍ、玉石積の基礎上に建ち、軸部は竪板張目板打ちで、黒色塗装を施す。屋根は、柱ごとに腕木を出して桁を受け、鉄板葺とする。もと庄屋屋敷に相応しい屋敷景観をみせる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006849"},{"id":"00006847","register_sub_id":"101","register_pk":"107829","name":"大箸家住宅納屋","kana":"おおはしけじゅうたくなや","category":"住宅","subcategory":"建築物","type_guess":"茶室・離れ","type_guess_confidence":"high","period":"昭和前","pref":"静岡県","address":"静岡県磐田市壱貫地字道上429-1","lat":34.826057,"lng":137.8349108,"geo_status":"db","era":"昭和前期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和前期","structure":"木造平屋一部2階建、瓦葺、建築面積78㎡","structure_material":"木造平屋一部2階建","registered":"2008.03.07(平成20.03.07)","register_no":"22 － 0128","desc":"主屋の東側、北土蔵の北方に西面して建つ。木造平屋一部２階建、切妻造桟瓦葺である。桁行４．５ｍ梁間３．６ｍの２階部分を中心に、南・東・北三方に一段低い平屋をまわし、西面に下屋吹放ち、北西隅に便所を付設する。屋根が重なる特徴的な外観をもつ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006847"},{"id":"00006846","register_sub_id":"101","register_pk":"107828","name":"大箸家住宅南土蔵","kana":"おおはしけじゅうたくみなみどぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"静岡県","address":"静岡県磐田市壱貫地字道上429-1","lat":34.82585048,"lng":137.83483499,"geo_status":"db","era":"明治前期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"土蔵造平屋建、瓦葺、建築面積47㎡","structure_material":"土蔵造平屋建","registered":"2008.03.07(平成20.03.07)","register_no":"22 － 0127","desc":"敷地入口の東側、北土蔵の前に北面して建つ。 桁行７．３ｍ梁間４．５ｍ、土蔵造２階建、切妻造桟瓦葺で、北側に１間通りに蔵前を付ける。伊豆石を積んだ基壇上に立ち、腰壁を海鼠壁とする。酒造関連の備品を収蔵した蔵で、歴史的な街路景観を形成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006846"},{"id":"00001073","register_sub_id":"101","register_pk":"102063","name":"大村家住宅","kana":"おおむらけじゅうたく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"low","period":"江戸","pref":"静岡県","address":"静岡県静岡市葵区平野1052","lat":35.14553325,"lng":138.36763328,"geo_status":"db","era":"江戸時代後期","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸時代後期","structure":"木造平屋建，茅葺，建築面積189㎡","structure_material":"木造平屋建","registered":"1999.02.17(平成11.02.17)","register_no":"22 － 0038","desc":"祖先が武田家の家臣であったとつたえる旧家で，住宅は安倍川の北に広がる緩斜面に建つ。養蚕のために屋根をかぶと造とした大規模な民家建築で，常盤新平の小説の舞台となる等，広く親しまれている。県内で数少ないかぶと造の民家としても貴重。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001073"},{"id":"00013252","register_sub_id":"101","register_pk":"366241","name":"小栗家住宅主屋","kana":"おぐりけじゅうたくおもや","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"静岡県","address":"静岡県沼津市上香貫字槇島町1336-1他","lat":35.08735,"lng":138.866775,"geo_status":"db","era":"明治後期／大正後期・昭和前期増築","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"木造平屋建、瓦葺、建築面積147㎡","structure_material":"木造平屋建","registered":"2020.04.03(令和2.04.03)","register_no":"22 － 0285","desc":"御用邸近くの別荘を、明治後期に移築したと伝わる住宅。東から玄関と和室二室、洋室、座敷をほぼ一列に並べる。主体部は桟瓦葺だが、洋室には青いスペイン瓦を葺く。座敷は富士山を望む北面に縁を廻らす。和風住宅の中央に洋館を挿入した特色ある構成の住宅。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013252"},{"id":"00014608","register_sub_id":"101","register_pk":"515150","name":"海瀬家住宅主屋","kana":"かいせけじゅうたくおもや","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"静岡県","address":"静岡県沼津市西浦河内171-1","lat":35.00984722,"lng":138.87094444,"geo_status":"db","era":"江戸末期／昭和4年頃改修","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造平屋建、瓦葺、建築面積223㎡","structure_material":"木造平屋建","registered":"2023.08.07(令和5.08.07)","register_no":"22 - 0318","desc":"伊豆半島北西の山間集落に建つ旧家の主屋。寄棟造平入桟瓦葺で元は茅葺。北東を土間、南西を六間取の床上部とする。背面側は内向きの室とし、開放的な正面三間続きの座敷は祭礼時に神輿を据えて神楽を奉納する。伊豆地方の名主の風格を伝える民家として貴重。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014608"},{"id":"00010976","register_sub_id":"101","register_pk":"208946","name":"川奈ホテル田舎家","kana":"かわなほてるいなかや","category":"住宅","subcategory":"建築物","type_guess":"ホテル","type_guess_confidence":"high","period":"江戸","pref":"静岡県","address":"静岡県伊東市川奈字ヒカゲ1460-4","lat":34.940365,"lng":139.140369,"geo_status":"db","era":"江戸後期／昭和11移築","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造平屋建、茅葺、建築面積227㎡","structure_material":"木造平屋建","registered":"2016.02.25(平成28.02.25)","register_no":"22-0220","desc":"本館北側に南北棟で東面して建つ、木造平屋建、入母屋造茅葺。南半を土間として五平の独立柱を立て、床上部は食違い四間取系とする。上手奥の八畳に床を構え、表二室は一五畳及び一二畳と広い。柱配置や部材加工等に古式をとどめる、戦前期の民家移築の好例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010976"},{"id":"00014612","register_sub_id":"101","register_pk":"515154","name":"川端家修善寺別邸主屋","kana":"かわばたけしゅぜんじべっていおもや","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和前","pref":"静岡県","address":"静岡県伊豆市修善寺1156-2他","lat":34.96953889,"lng":138.91909722,"geo_status":"db","era":"昭和17年","year":1942,"year_source":"db","year_min":1942,"year_max":1942,"year_label":null,"structure":"木造平屋建、瓦葺一部銅板葺、建築面積147㎡","structure_material":"木造平屋建","registered":"2023.08.07(令和5.08.07)","register_no":"22 - 0322","desc":"修善寺温泉地区に建つ画家川端龍子の別邸。主体部と台所を渡廊下で結び、外装は土壁の真壁と木賊張等からなる。大判ガラス引分戸で仕切る開放的な広間、梅の枝に見立てた絵画的な欄間や要所の網代張が特徴的。龍子の嗜好が反映された独創的な近代和風建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014612"},{"id":"00014613","register_sub_id":"101","register_pk":"515155","name":"川端家修善寺別邸門","kana":"かわばたけしゅぜんじべっていもん","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"昭和前","pref":"静岡県","address":"静岡県伊豆市修善寺1156-2","lat":34.96986111,"lng":138.91939167,"geo_status":"db","era":"昭和17年頃／令和3年改修","year":1942,"year_source":"db","year_min":1942,"year_max":1942,"year_label":null,"structure":"木造、瓦葺、間口2.3m、袖塀付","structure_material":"木造","registered":"2023.08.07(令和5.08.07)","register_no":"22 - 0323","desc":"画家川端龍子の別邸敷地の北東隅に建つ桟瓦葺表門。本柱に太い角柱を抱き合わせ、後方に肘木状の腕木を差出し、中備を人字形割束とし、垂木は吹寄とする。形式にとらわれず伝統的な建築要素を巧みに取込んだ意欲的なデザインで、道沿いの屋敷構えを整える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014613"},{"id":"00015021","register_sub_id":"101","register_pk":"529299","name":"旧石川家清水別邸（三樹庵）主屋","kana":"きゅういしかわけしみずべってい（さんじゅあん）おもや","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和前","pref":"静岡県","address":"静岡県静岡市清水区村松3238","lat":34.98945,"lng":138.48476944,"geo_status":"db","era":"昭和15年／昭和45年頃増築","year":1940,"year_source":"db","year_min":1940,"year_max":1940,"year_label":null,"structure":"木造平屋建一部地階付、瓦葺、建築面積253㎡","structure_material":"木造平屋建一部地階付","registered":"2024.08.15(令和6.08.15)","register_no":"22 - 0331","desc":"富士山を望む日本平東麓の農園に建つ別邸主屋。宝形造本瓦葺の接客部の南に寄棟造桟瓦葺の居住部、北に切妻造桟瓦葺の家政部を配す。接客部は太い柱を差物で固めた民家風、居住部は舟底天井など端正な数寄屋風とする。平面や意匠に変化のある上質な別邸建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015021"},{"id":"00012931","register_sub_id":"101","register_pk":null,"name":"旧井上侯爵家熱海別邸（清光園）","kana":"きゅういのうえこうしゃくけあたみべってい（せいこうえん）","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"静岡県","address":"静岡県熱海市泉元宮上分字塩坪26-7他","lat":35.14387222,"lng":139.07710833,"geo_status":"db","era":"昭和前期／昭和60年移築・改修","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和前期","structure":"木造平屋一部2階建、瓦葺、建築面積151㎡","structure_material":"木造平屋一部2階建","registered":"2019.09.10(令和1.09.10)","register_no":"22 － 281","desc":"湯河原温泉の一角に建つ。寄棟造桟瓦葺の二階建、外壁は簓子下見板張の小壁漆喰塗。南東二面の開口を広く取り、軒丸太垂木や二階室内に数寄屋意匠を取り入れる。一階東北隅の居間は台形の張出し窓や造付の長椅子を備える。開放的で落ち着いた佇まいの旧別邸。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012931"},{"id":"00012906","register_sub_id":"101","register_pk":"368009","name":"旧岩邊家住宅主屋","kana":"きゅういわなべけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"静岡県","address":"静岡県静岡市清水区蒲原新田一丁目2154-1","lat":35.11726389,"lng":138.599175,"geo_status":"db","era":"安政5年（1858）頃／昭和7年移築、昭和前期改修","year":1858,"year_source":"db","year_min":1858,"year_max":1858,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積169㎡","structure_material":"木造平屋建","registered":"2019.09.10(令和1.09.10)","register_no":"22 － 256","desc":"旧蒲原宿西辺にある間口六間の町家。主屋は街道に北面して建つ切妻造桟瓦葺の平屋建、軒出桁造で、正面下屋に格子を並べる。東に幅二間のタイル敷土間を通して梁組を現し、西に二列に室を並べ、西列前二室を座敷とする。近世蒲原宿の風情を伝える貴重な遺構。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012906"},{"id":"00012908","register_sub_id":"101","register_pk":"368011","name":"旧岩邊家住宅土蔵","kana":"きゅういわなべけじゅうたくどぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"昭和前","pref":"静岡県","address":"静岡県静岡市清水区蒲原新田一丁目2154-1","lat":35.11710278,"lng":138.59915833,"geo_status":"db","era":"昭和2年頃","year":1927,"year_source":"db","year_min":1927,"year_max":1927,"year_label":null,"structure":"木造2階建、瓦葺、建築面積40㎡","structure_material":"木造2階建","registered":"2019.09.10(令和1.09.10)","register_no":"22 － 258","desc":"離れの北側に連なって南北棟で建つ。寄棟造桟瓦葺の二階建。一階は土蔵造、外壁海鼠壁で、東面二箇所の倉庫出入口を黒漆喰塗とする。二階は下見板張で、離れとつながる座敷を設け、庭に面する東面を掃出し窓とする。独特な形式をもつ近代住宅の附属建物。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012908"},{"id":"00012907","register_sub_id":"101","register_pk":"368010","name":"旧岩邊家住宅離れ","kana":"きゅういわなべけじゅうたくはなれ","category":"住宅","subcategory":"建築物","type_guess":"茶室・離れ","type_guess_confidence":"high","period":"大正","pref":"静岡県","address":"静岡県静岡市清水区蒲原新田一丁目2154-1","lat":35.11697778,"lng":138.59917778,"geo_status":"db","era":"大正後期","year":1922,"year_source":"estimated","year_min":1919,"year_max":1926,"year_label":"大正後期","structure":"木造平屋建、瓦葺、建築面積88㎡","structure_material":"木造平屋建","registered":"2019.09.10(令和1.09.10)","register_no":"22 － 257","desc":"敷地中央西寄りに南北棟で建つ。寄棟造桟瓦葺の平屋建、東面北寄りに玄関を構え、外壁を真壁漆喰塗とする。内部は大振りの座敷飾を備えた一五畳の主座敷と八畳の次の間を南北に並べ、庭に面する南東二面に四尺幅の縁を廻す。開放的かつ瀟洒な意匠の離れ座敷。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012907"},{"id":"00014024","register_sub_id":"101","register_pk":"508284","name":"旧岸邸","kana":"きゅうきしてい","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和後","pref":"静岡県","address":"静岡県御殿場市東山字木戸下1082-1他","lat":35.29452222,"lng":138.96055,"geo_status":"db","era":"昭和44年／平成20年改修","year":1969,"year_source":"db","year_min":1969,"year_max":1969,"year_label":null,"structure":"木造平屋建一部鉄筋コンクリート造2階建、スレート葺、建築面積412㎡","structure_material":"木造平屋建一部鉄筋コンクリート造2階建","registered":"2021.10.14(令和3.10.14)","register_no":"22 - 0313","desc":"東名高速道路御殿場インター近くに構える岸信介の本邸。居間・和室等よりなる庭に面した接客空間を中心に、サービス空間、二階の居住空間を配し、全体を「日本的コッテージ風」でまとめ、洗練された戦後の和風建築。吉田五十八晩年の代表作の一つ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014024"},{"id":"00013118","register_sub_id":"101","register_pk":"368275","name":"旧小松宮別邸桜御殿","kana":"きゅうこまつのみやべっていさくらごてん","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"静岡県","address":"静岡県三島市一番町2682-1","lat":35.12392222,"lng":138.91193889,"geo_status":"db","era":"明治25年","year":1892,"year_source":"db","year_min":1892,"year_max":1892,"year_label":null,"structure":"木造2階建、瓦葺、建築面積144㎡","structure_material":"木造2階建","registered":"2019.12.05(令和1.12.05)","register_no":"22 － 0283","desc":"旧小松宮家別邸の敷地北側の高台に建つ。木造二階建で上下階とも主室ほか数室を配し、南の小浜池や北西の富士山側を開放的にして眺望を確保する。全体を気品ある書院造としつつ主座敷の床柱を皮付きや磨き丸太の桜木とするなど独創性も交えた宮家の別邸。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013118"},{"id":"00013554","register_sub_id":"101","register_pk":"504921","name":"旧桜井家住宅主屋（島田市博物館分館）","kana":"きゅうさくらいけじゅうたくおもや（しまだしはくぶつかんぶんかん）","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"静岡県","address":"静岡県島田市河原二丁目4257-18","lat":34.83217778,"lng":138.15664444,"geo_status":"db","era":"明治32年／昭和40年代改修、平成12年改修","year":1899,"year_source":"db","year_min":1899,"year_max":1899,"year_label":null,"structure":"木造2階建、瓦葺 建築面積291㎡","structure_material":"木造2階建","registered":"2021.02.04(令和3.02.04)","register_no":"22 － 0289","desc":"島田市の中心部に位置する。平屋建一部二階建寄棟造桟瓦葺。通りから引いて建ち、玄関からの土間沿いに二列七室を配した農家風平面の主体部に、さらに上手に二階建、手前に平屋建の座敷棟を接続する。豪壮な邸宅として庭木等とともに良好な景観を形成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013554"},{"id":"00010973","register_sub_id":"101","register_pk":"208943","name":"旧静岡英和女学院院長住宅主屋","kana":"きゅうしずおかえいわじょがくいんいんちょうじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和中","pref":"静岡県","address":"静岡県静岡市葵区西深草町34-5","lat":34.98355,"lng":138.378849,"geo_status":"db","era":"昭和25","year":1950,"year_source":"db","year_min":1950,"year_max":1950,"year_label":null,"structure":"木造2階建一部地階付、瓦葺、建築面積113㎡","structure_material":"木造2階建一部地階付","registered":"2016.02.25(平成28.02.25)","register_no":"22-0217","desc":"閑静な住宅地に建つ。外観は白色で平明な立面に、出隅部など内法全高の開口を連続させ採光し、モダニズムへの指向が読み取れる。一階は南テラスをＬ・Ｄ・Ｋの各室で囲み、居間に暖炉を備える。住生活への配慮と洋風内装にヴォーリズ事務所の特徴が窺える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010973"},{"id":"00009180","register_sub_id":"101","register_pk":"164733","name":"旧菅沼家住宅（知半庵）主屋","kana":"きゅうすがぬまけじゅうたく（ちはんあん）しゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"静岡県","address":"静岡県伊豆の国市吉田字城内623-1","lat":34.999722,"lng":138.94174624,"geo_status":"db","era":"文化5年(1808)頃／昭和41年・昭和49年・平成6年改修","year":1808,"year_source":"db","year_min":1808,"year_max":1808,"year_label":null,"structure":"木造平屋建、茅葺（鉄板仮葺）、建築面積175㎡","structure_material":"木造平屋建","registered":"2012.02.23(平成24.02.23)","register_no":null,"desc":"下田街道沿いの敷地西寄りに西面して建つ。桁行19.2メートル梁間9.1メートル、平屋建、寄棟造茅葺で、鉄板を仮葺する。南半がもと土間で大戸口を開き、床上部は前後2列に6室を配し、奥座敷に大ドコを構える。伊豆地方における上層農家の住宅。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009180"},{"id":"00009181","register_sub_id":"101","register_pk":"164734","name":"旧菅沼家住宅（知半庵）門及び塀","kana":"きゅうすがぬまけじゅうたく（ちはんあん）もんおよびへい","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"昭和前","pref":"静岡県","address":"静岡県伊豆の国市吉田字城内623-1","lat":34.99985168,"lng":138.94160467,"geo_status":"db","era":"昭和10年","year":1935,"year_source":"db","year_min":1935,"year_max":1935,"year_label":null,"structure":"門 石造、間口3.6m 塀 石造、総延長32m","structure_material":"門 石造","registered":"2012.02.23(平成24.02.23)","register_no":null,"desc":"主屋大戸口の正面に門を構えて左右に塀を延ばし、いずれも地元産の小室石を使用する。門は高さ2.6メートルの門柱1対を間口3.6メートルに立てる。塀は高さ1.8メートル、総延長32メートルを測り、基礎石上に切石を4段積み、笠石を載せる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009181"},{"id":"00015195","register_sub_id":"101","register_pk":"530619","name":"旧鈴木家住宅弓道場的場","kana":"きゅうすずきけじゅうたくきゅうどうじょうまとば","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"静岡県","address":"静岡県浜松市中央区中郡町字万斛西980","lat":34.77367778,"lng":137.77425278,"geo_status":"db","era":"昭和6年","year":1931,"year_source":"db","year_min":1931,"year_max":1931,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積16㎡","structure_material":"木造平屋建","registered":"2024.12.03(令和6.12.03)","register_no":"22 - 0336","desc":"旧家の屋敷に由来する公園内の弓道場の的場。射場と相対し矢道を介し南面して建つ。切妻造桟瓦葺で壁は真壁漆喰塗。南面東寄りを吹放ち、内部の安土に的を据える。西端は物置。簡素ながらも太い桁など力強いつくりで、矢場と呼応し戦前の弓道の隆盛を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015195"}];
